const LOTES = [{"id":"ni2025-enfermeiro","cargo":"Analista Técnico em Qualificação, Seleção e Fiscalização de Entidades Prestadoras de Saúde — Enfermeiro","prova":"https://conhecimento.fgv.br/sites/default/files/concursos/analista-tecnico-em-qualificacao-selecao-e-fiscalizacao-de-entidades-prestadoras-de-saude-enfermeiro-cns003-tipo-1.pdf","gabarito":"https://conhecimento.fgv.br/sites/default/files/concursos/gabarito-definitivo-smsnovaiguacu.pdf","itens":[{"n":2,"disciplina":"Língua Portuguesa","assunto":"Coordenação e Subordinação","enunciado":"Sobre a propaganda “Se beber, não dirija”, avalie as sentenças a seguir. I. A oração subordinada veicula ideia de condição. II. É possível trocar a ordem das orações, subordinada e principal, sem que haja alteração de sentido. III. A pontuação se justifica pela inversão da ordem da oração principal. IV. O conectivo poderia ser substituído, sem alteração de sentido, por “desde que”. Está correto o que se afirma em","alternativas":["I e II, apenas.","I e IV, apenas.","II e III, apenas.","II e IV, apenas.","I, II, III e IV"],"gabarito":"E"},{"n":3,"disciplina":"Língua Portuguesa","assunto":"Semântica e Significação","enunciado":"Na frase: “Maria disse à Joana que ela seria selecionada para a vaga”, a ambiguidade é causada em função","alternativas":["da polissemia de um termo.","da imprecisão do referente.","do uso incorreto do hiperônimo.","do conectivo generalizante.","da abrangência do termo resumitivo"],"gabarito":"B"},{"n":5,"disciplina":"Língua Portuguesa","assunto":"Ortografia e Acentuação","enunciado":"Assinale a opção gramaticalmente correta.","alternativas":["Os professores não aderiram à paralização.","Este é um exemplo de mal uso do dinheiro público.","Há muita sujeira em baixo da mesa.","A última seção do filme já vai começar.","Comeu bastantes salgadinhos na festa da prima."],"gabarito":"E"},{"n":6,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Equivalências e Negações","enunciado":"Considere a seguinte afirmação: Todo restaurante capixaba vende moqueca e caranguejada. A negação dessa proposição é logicamente equivalente a","alternativas":["Há, pelo menos, um restaurante capixaba que não vende moqueca ou não vende caranguejada.","Há, pelo menos, um restaurante capixaba que não vende moqueca, nem vende caranguejada.","Todos os restaurantes capixabas não vendem moqueca ou não vendem caranguejada.","Todos os restaurantes capixabas não vendem moqueca, nem vendem caranguejada.","Todo restaurante que não vende moqueca, nem vende caranguejada, não é capixaba"],"gabarito":"A"},{"n":7,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Regra de Três e Problemas Aritméticos","enunciado":"A dosagem máxima diária de um medicamento administrável a uma pessoa em tratamento é calculada a partir da proporção de 4 gotas para cada 1,5 kg de sua massa corporal. O número de gotas desse medicamento que compõe a dosagem máxima administrável a uma pessoa com 75 kg, é de","alternativas":["300.","200.","150.","100.","50"],"gabarito":"B"},{"n":10,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Análise Combinatória","enunciado":"O setor de Emergência de um hospital monta as suas equipes plantonistas com especialistas nas áreas de Obstetrícia, Pneumologia, Cardiologia e Ortopedia. O quadro de plantonistas conta com 5 especialistas de cada área e as equipes plantonistas são montadas com 2 especialistas de cada área. O número máximo de equipes plantonistas distintas, que podem ser montadas, é","alternativas":["10 000.","1 250.","625.","40.","25."],"gabarito":"A"},{"n":11,"disciplina":"Legislação do SUS","assunto":"Decreto 7.508/2011","enunciado":"O Conselho Municipal de Saúde recebeu denúncias sobre dificuldades no acesso a consultas especializadas e exames entre municípios da região. O gestor propôs articular ações interfederativas por meio da Comissão Intergestores Regional (CIR) para organizar o atendimento e partilhar responsabilidades entre os entes federativos. As principais normas que orientam essa situação são:","alternativas":["Lei nº 8.080/1990, Lei nº 8.142/1990 e Lei nº 8.666/1993.","Lei nº 8.142/1990, Decreto nº 7.508/2011 e Lei nº 8.666/1993.","Constituição Federal de 1988, Lei nº 8.142/1990 e Decreto nº 7.508/2011.","Constituição Federal de 1988, Lei nº 8.080/1990 e Decreto nº 7.508/2011.","Lei nº 8.080/1990, Decreto nº 7.508/2011 e Lei nº 8.666/1993"],"gabarito":"D"},{"n":12,"disciplina":"Legislação do SUS","assunto":"Lei 8.080/1990 - Princípios e Diretrizes","enunciado":"Em uma Unidade de Saúde foi priorizado o atendimento de um idoso com múltiplas comorbidades, enquanto outros usuários aguardavam. Essa decisão foi justificada pela equipe como forma de atender às maiores necessidades em saúde. O princípio do SUS que justifica a decisão da equipe é o de","alternativas":["universalidade.","equidade.","integralidade.","regionalização.","participação social"],"gabarito":"B"},{"n":13,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"Uma forte chuva ocorrida em região urbana resultou em inundações em diferentes bairros da cidade, causando a interrupção de serviços essenciais. Após as enchentes, houve um aumento de casos de leptospirose e de doenças respiratórias, além de relatos de acidentes de trabalho e preocupações ambientais relacionadas à qualidade do ar e ao lixo acumulado. Considerando esse contexto, analise os itens a seguir. I. A vigilância epidemiológica contribuirá para monitorar a incidência de doenças transmissíveis e detectar rapidamente novos casos que possam surgir após o desastre. II. A vigilância sanitária será importante na fiscal ização do abastecimento de água e alimentos, além de garantir o cumprimento de normas de higiene e segurança das estruturas públicas e privadas afetadas. III. A vigilância em saúde ambiental se encarregará de identificar fatores de risco relacionados à qualidade do ar, ao acúmulo de lixo e às condições do solo e da água, promovendo ações de controle e mitigação. Está correto o que se afirma em","alternativas":["I e II, apenas.","III, apenas.","I e III, apenas.","II e III, apenas.","I, II e III."],"gabarito":"E"},{"n":14,"disciplina":"Enfermagem","assunto":"Imunização","enunciado":"Em março de 2025, a Prefeitura de Nova Iguaçu promoveu vacinação itinerante contra a influenza, com o “Ônibus da Saúde” percorrendo locais de grande circulação, das 8h às 14h. Além da vacina contra a gripe, foram oferecidas vacinas de rotina, como sarampo e Covid-19. Fonte: Prefeitura de Nova Iguaçu (31/03/2025). A iniciativa amplia o acesso da população às vacinas e complementa o trabalho das unidades básicas de saúde. Analise as afirmativas a seguir e classifique -as como verdadeiras (V) ou falsas (F). ( ) A vacinação itinerante exemplifica a universalidade do SUS e a PNAB, que organiza as ações de imunização na Atenção Básica. ( ) A iniciativa assegura universalidade e integralidade ao oferecer acesso irrestrito e cuidado contínuo. ( ) Com a CF/88 e a Lei nº 8.080/1990, a saúde passou a ser direito universal e dever do Estado, incluindo a vacinação na Atenção Básica. ( ) A vacinação itinerante, com apoio das equipes da ESF, demonstra integração entre Vigilância Epidemiológica e PNAB. As afirmativas são, respectivamente:","alternativas":["V – V – V – F.","V – V – V – V.","F – V – V – F.","V – V – F – V.","V – F – V – F"],"gabarito":"E"},{"n":15,"disciplina":"Legislação do SUS","assunto":"Redes de Atenção à Saúde","enunciado":"Em agosto de 2025, a Prefeitura de Nova Iguaçu realizou mutirão com atendimentos especializados e vacinação, pelo programa federal “Agora Tem Especialistas”, aplicando a metodologia de Oferta de Cuidados Integrados (OCI), que reúne consultas, exames e diagnóstico em um único fluxo. Fonte: Prefeitura de Nova Iguaçu (09/08/2025). A OCI integra procedimentos clínicos, diagnósticos e de gestão, fortalecendo a Atenção Básica e promovendo cuidado contínuo no território. Analise as afirmativas a seguir e classifique -as como verdadeiras (V) ou falsas (F): ( ) A metodologia de Oferta de Cuidados Integrados fortalece a Atenção Primária e o atributo da longitudinalidade da PNAB. ( ) O financiamento do SUS é tripartite, envolvendo União, estados e municípios. ( ) A OCI expressa o princípio da integralidade e reforça a continuidade do cuidado no território. ( ) A PNAB define a imunização e o cuidado o ncológico como atribuições exclusivas da atenção especializada. As afirmativas são, respectivamente","alternativas":["V – F – V – F.","F – V – V – F.","V – V – F – V.","V – V – V – V.","V – V – V – F. Gestão de Parcerias"],"gabarito":"E"},{"n":16,"disciplina":"Legislação do SUS","assunto":"Constituição Federal - Saúde","enunciado":"A Constituição Federal de 1988 estabelece que a saúde é direito de todos e dever do Estado, devendo ser garantida por meio de políticas sociais e econômicas, com acesso universal e igualitário. Nesse sentido, cabe ao Poder Público","alternativas":["considerar a saúde como atividade sujeita às regras do mercado.","exercer a função de regulamentar, fiscalizar e controlar os serviços.","assegurar o direito por meio da ampliação da rede privada de serviços.","priorizar a execução das ações por meio da estrutura administrativa estatal.","delegar a gestão integral das ações de saúde a entidades privadas contratadas"],"gabarito":"B"},{"n":17,"disciplina":"Legislação do SUS","assunto":"Constituição Federal - Saúde","enunciado":"A Constituição Federal de 1988, em seu art. 197, dispõe que as ações e os serviços de saúde são de relevância pública, cabendo ao Poder Público regulamentar, fiscalizar e controlar sua execução. Esse dispositivo admite que tais serviços sejam realizados por terceiros, o que, na prática, permitiu o desenvolvimento de parcerias reguladas por leis posteriores. Nessa perspectiva, a execução indireta das ações dos serviços de saúde pode envolver:","alternativas":["partidos políticos registrados no Tribunal Superior Eleitoral.","órgãos da administração direta de qualquer esfera federativa.","empresas públicas com exclusividade em serviços assistenciais.","entidades do terceiro setor, sob fiscalização e controle do Poder Público.","conselhos de classe profissional, sem necessidade de regulação estatal"],"gabarito":"D"},{"n":18,"disciplina":"Direito Administrativo","assunto":"Organização Administrativa","enunciado":"As Organizações Sociais (OSs) constituem uma das formas de parceria entre Estado e sociedade civil, previstas em lei. As OSs desempenham papel relevante na gestão de serviços públicos, especialmente na área da saúde, mediante","alternativas":["autorizações administrativas concedidas de forma precária e unilateral.","contratos privados de prestação de serviços, sem mecanismos de controle.","convênios de cooperação estabelecidos entre órgãos e entidades públicas.","concessões de serviços públicos voltadas a atividad es de caráter econômico.","contratos de gestão que fixam metas, indicadores e acompanhamento estatal."],"gabarito":"E"},{"n":19,"disciplina":"Direito Administrativo","assunto":"Organização Administrativa","enunciado":"A Lei nº 9.637/1998 estabelece requisitos específicos para que entidades privadas possam ser qualificadas como Organizações Sociais (OSs). Entre esses requisitos, está a obrigatoriedade de","alternativas":["registro de seus atos constitutivos sobre a natureza social em cartório, após o início da parceria.","distribuição anual de seus excedentes financeiros entre os membros da diretoria colegiada.","previsão de participação de membros da comunidade no órgão colegiado de deliberação superior.","comprovação de finalidade não -lucrativa com incorporação integral do patrimônio e de resultados aos voluntários.","distribuição de bens ou de parcela do patrimônio líqu ido, em razão de falecimento de associado ou membro da entidade"],"gabarito":"C"},{"n":20,"disciplina":"Direito Administrativo","assunto":"Organização Administrativa","enunciado":"A Lei nº 9.637/1998 prevê que o Conselho de Administração é o órgão de deliberação superior das Organizações Sociais (OSs), responsável por funções de direção e controle, essenciais à gestão dessas entidades. Assinale a opção que apresenta corretamente uma de suas atribuições privativas.","alternativas":["Aprovar a proposta de orçamento da entidade e o programa de investimentos.","Autorizar a proposta de contrato de gestão da entidade com empresas privadas.","Homologar concursos públicos para a contratação de servidores estatutários.","Conceder participação nos lucros aos empregados e voluntários da entidade.","Negociar a remuneração dos membros da diretoria colegiada conforme desempenho"],"gabarito":"A"},{"n":21,"disciplina":"Direito Administrativo","assunto":"Licitações e Contratos","enunciado":"A Lei nº 9.637/1998 define o contrato de gestão como o instrumento firmado entre o Poder Público e a entidade qualificada como Organização Social (OS), estabelecendo as atribuições, responsabilidades e obrigações de ambas as partes. Esse contrato deve conter obrigatoriamente a","alternativas":["especificação do programa de trabalho proposta pelo Poder Público.","previsão de lucro distribuível entre os associados da OS contratada.","exclusividade de gestão para a administração pública direta, na área pactuada.","estipulação dos limites para despesa com remuneração a ser percebida pelos dirigentes e voluntários.","especificação do programa de trabalho, metas, prazos de execução e critérios de avaliação de desempenho"],"gabarito":"E"},{"n":26,"disciplina":"Direito Administrativo","assunto":"Organização Administrativa","enunciado":"A entidade qualificada como Organização Social (OS) é declarada de interesse social e utilidade pública, para todos os efeitos legais. Nessa perspectiva, os responsáveis pela fiscalização da execução do contrato de gestão, ao tomarem conhecimento de qualquer irregularidade na utilização de recursos ou bens públicos, devem","alternativas":["arquivar o relatório de fiscalização, salvo quando houver reincidência da irregularidade.","suspender imediatamente o contrato, sem necessidade de comunicação a outros órgãos.","instaurar diretamente processo administrativo disciplinar contra os dirigentes da entidade.","comunicar o fato ao Tribunal de Contas da União, sob pena de responsabilidade solidária.","encaminhar a denúncia exclusivamente ao Ministério Público, para as providências cabíveis"],"gabarito":"D"},{"n":27,"disciplina":"Legislação do SUS","assunto":"Redes de Atenção à Saúde","enunciado":"Nas contratações complementares de serviços de saúde, deverão ser observados os princípios e as diretrizes do SUS, bem como a necessidade de ampliação da oferta e os recursos disponíveis. A previsão dessas necessidades deve integ rar os instrumentos de planejamento do SUS, de modo que","alternativas":["a Programação Anual de Saúde seja facultativa para municípios com menos de 50 mil habitantes.","o Plano Municipal de Saúde seja elaborado anualmente, devendo ser submetido ao Conselho Nacional de Saúde.","o Plano Municipal de Saúde apresente metas detalhadas de execução anual, dispensando a Programação Anual de Saúde.","a Programação Anual de Saúde substitua o Relatório Anual de Gestão, visto que eles têm a mesma função de avaliação.","o Plano Municipal de Saúde contenha a previsão das necessidades com detalhamento na Programação Anual de Saúde"],"gabarito":"E"},{"n":28,"disciplina":"Direito Administrativo","assunto":"Agentes Públicos","enunciado":"O art. 37, IX, da Constituição Federal de 1988, autoriza que a lei estabeleça os casos de contratação por tempo determinado para atender a necessidade temporária de excepcional interesse público. Essa regra deve ser interpretada em consonância com os princípios constitucionais da Administração Pública. Nesse sentido, é correto afirmar que","alternativas":["a publicidade garante a inexigibilidade de di vulgação dos contratos temporários, já que sua natureza é emergencial.","a eficiência autoriza contratações temporárias ilimitadas, desde que atendam à necessidade administrativa.","a impessoalidade permite a livre escolha de contratados pelo administrador, sem critérios objetivos ou previamente definidos.","a observância do princípio da legalidade exige que as hipóteses de contratação temporária estejam previstas em lei específica.","a contratação temporária atende ao princípio da moralidade, quando é utilizada como substituto permanente do concurso público"],"gabarito":"D"},{"n":29,"disciplina":"Legislação do SUS","assunto":"Lei 8.080/1990 - Princípios e Diretrizes","enunciado":"De acordo com o art. 199, §1º, da Constituição Federal de 1988, a participação de instituições privadas no Sistema Único de Saúde (SUS) ocorre de forma complementar, observadas as diretrizes do sistema. Nessa hipótese, a Constituição estabelece que","alternativas":["a livre iniciativa dispensa qualquer ordem de preferência na contratação.","a contratação com instituições privadas é restrita a situações emergenciais e temporárias.","a participação privada no SUS se dá exclusivamente por meio de concessões de serviços públicos.","a contratação deve priorizar entidades com fins lucrativos, em razão da maior capacidade de investimento.","as entidades filantrópicas e sem fins lucrativos têm preferência na formalização dos contratos ou convênios"],"gabarito":"E"},{"n":30,"disciplina":"Direito Administrativo","assunto":"Controle da Administração Pública","enunciado":"O monitoramento, a avaliação e a fiscalização dos contratos na área da saúde são instrumentos essenciais de defesa do interesse público, assegurando que os serviços sejam prestados com qualidade e em conformidade com as metas estabelecidas. Compete à Comissão de Acompanhamento, no processo de execução contratual,","alternativas":["avaliar o cumprimento das metas quali-quantitativas e físico- financeiras.","elaborar relatórios de acompanhamento restritos à análise contábil dos repasses financeiros.","fiscalizar a execução contratual de forma complementar ao setor demandante, sem prejuízo de suas atribuições.","autorizar a continuidade da execução contratual quando constatadas falhas graves justificadas pela contratada.","censurar denúncias recebidas para descredenciamento da entidade que descumprir as obrigações constantes do contrato"],"gabarito":"A"},{"n":31,"disciplina":"Direito Administrativo","assunto":"Licitações e Contratos","enunciado":"Nos contratos administrativos de prestação de serviços de saúde de natureza contínua, o prazo de vigência pode ser prorrogado por iguais e sucessivos períodos até o limite de 60 meses, conforme prevê a legislação. Sobre a análise da prestação de contas e dos relatórios de execução, é correto afirmar que","alternativas":["os relatórios de execução contratual substituem a necessidade de prestação de contas junto aos órgãos de controle.","a coincidência entre vigência contratual e ano civil é exigência legal absoluta para facilitar a consolidação orçamentária.","a prestação de contas deve ser realizada ao final do exercício financeiro, ainda que o contrato tenha duração superior a um ano civil.","a prorrogação contratual além de 60 meses somente é admitida em caso de atraso na apresentação dos relatórios de execução financeira.","a duração dos contratos contínuos deve coincidir obrigatoriamente com o exercício financeiro, vedada a prorrogação que ultrapasse o ano civil."],"gabarito":"C"},{"n":32,"disciplina":"Direito Administrativo","assunto":"Licitações e Contratos","enunciado":"O Marco Regulatório das Organizações da Sociedade Civil (MROSC – Lei nº 13.019/2014) instituiu novos instrumentos jurídicos para a formalização de parcerias entre o poder público e entidades privadas sem fins lucrativos. Considerando essa legislação, é correto afirmar que","alternativas":["o termo de parceria é o único instrumento admitido pelo MROSC, substituindo convênios, termos de colaboração e termos de fomento.","o contrato de gestão é o instrumento típico do MROSC, utilizado para parcerias com Organizações da Sociedade Civil de Interesse Público (OSCIPs).","o MROSC não prevê transferência de recursos financeiros, restringindo-se a parcerias de cooperação técnica sem ônus para o poder público.","o termo de fomento é utilizado quando a proposta de parceria é apresentada pela organização da sociedade civil, prevendo repasse de recursos financeiros.","o termo de colaboração é firmado quando a proposta de parceria parte da própria organização da sociedade civil, envolvendo transferência de recursos públicos"],"gabarito":"D"},{"n":33,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"Os Sistemas de Informação em Saúde instrumentalizam e apoiam a gestão do SUS em processos como planejamento, programação, regulação, controle, avaliação e auditoria. A utilização integrada desses sistemas permite à Administração Pública tomar decisões mais qualificadas sobre alocação de recursos e monitoramento do desempenho dos serviços. Considerando esse contexto, é correto afirmar que","alternativas":["o SIM e o SINASC são utilizados para regulação do acesso a procedimentos eletivos de média e alta complexidade.","o SISAB/e-SUS AB é dedicado exclusivamente ao acompanhamento de gastos hospitalares e de alta complexidade no SUS.","o SISREG registra informações sobre estabelecimentos e profissionais de saúde, servindo de base cadastral para auditorias do SUS.","o CNES é voltado prioritariamente ao registro de óbitos e nascimentos, sendo fundamental para estudos epidemiológicos sobre mortalidade e natalidade.","o SIH/SUS e o SIA/SUS produzem informações essenciais para o monitoramento de internações e procedimentos ambulatoriais, constituindo instrumentos de avaliação físico- financeira. Fiscalização de Contratos - Enfermagem"],"gabarito":"E"},{"n":34,"disciplina":"Enfermagem","assunto":"Gestão em Enfermagem","enunciado":"Há um tipo de auditoria que ocorre enquanto o paciente recebe atendimento e envolve a obtenção e avaliação de evidências a respeito da eficiência e eficácia das atividades operacionais de uma instituição, em comparação com os objetivos estabe lecidos, além de contemplar recomendações para aperfeiçoamento. Essa auditoria é classificada como","alternativas":["preventiva.","operacional.","analítica.","retrospectiva.","prospectiva"],"gabarito":"B"},{"n":35,"disciplina":"Enfermagem","assunto":"Processo de Enfermagem e SAE","enunciado":"Segundo a Resolução COFEN Nº 736/2024, analise as afirmativas a seguir sobre o Processo de Enfermagem, classificando -as como verdadeira (V) ou falsa (F). ( ) É um método que orienta o pensamento crítico e o julgamento clínico do enfermeiro direcionando a equipe de Enfermagem para o cuidado à pessoa, à família, à coletivida de e a grupos especiais. ( ) A documentação do Processo de Enfermagem deve ser realizada pelos membros da equipe formalmente no prontuário do paciente, físico ou eletrônico. ( ) Organiza-se em cinco etapas inter -relacionadas, interdependentes, recorren tes e cíclicas: Avaliação de Enfermagem, Diagnóstico de Enfermagem, Planejamento de Enfermagem, Implementação de Enfermagem e Evolução de Enfermagem. ( ) O registro de todas as suas etapas cabe a todos os membros da equipe de Enfermagem. As afirmativas são, respectivamente,","alternativas":["F – V – F – V.","V – F – F – F.","V – V – V – F.","F – V – V – F.","V – V – V – V"],"gabarito":"C"},{"n":36,"disciplina":"Enfermagem","assunto":"Segurança do Paciente","enunciado":"Indicadores são medidas quantitativas utilizadas para monitorar e avaliar atividades. Na saúde, destacam-se os indicadores de risco, relacionados a incidentes e eventos adversos. Cada instituição adapta sua lista de indicadores às próprias necessidades, que podem ser classificados em assistenciais e gerenciais (CQH, 2012). Sobre a classificação de indicadores de risco relacionado s a incidentes ou eventos adversos, analise os itens a seguir. I. Incidência de instrumentais cirúrgicos com sujidade. II. Incidência de flebite. III. Taxa de acidente de trabalho de profissionais de enfermagem. São indicadores de risco gerencial","alternativas":["I, apenas.","I e III, apenas.","II, apenas.","III, apenas.","I, II e III."],"gabarito":"B"},{"n":37,"disciplina":"Enfermagem","assunto":"Ética e Legislação em Enfermagem","enunciado":"De acordo com o art. 82, § 4º, do Código de Ética dos Profissionais de Enfermagem, o segredo profissional referente ao menor de idade deverá ser mantido, desde que o menor tenh a capacidade de discernimento, exceto nos casos em que","alternativas":["a revelação seja solicitada por pais ou responsáveis.","o segredo possa acarretar danos ou riscos ao menor.","possuir consentimento escrito do representante legal do menor.","o fato seja de conhecimento público.","não possuir consentimento do menor"],"gabarito":"B"},{"n":38,"disciplina":"Enfermagem","assunto":"Gestão em Enfermagem","enunciado":"A análise de contas e a produção de Enfermagem envolvem o acompanhamento de procedimentos realizados, uso de materiais e medicamentos, além do cálculo de taxas que refletem a qualidade e a eficiência da assistência prestada. Nesse contexto, assinale a afirmativa incorreta.","alternativas":["A conferência de materiais e medicamentos registrados em prontuário e nas contas hospitalares permite identificar inconsistências e evitar glosas.","A taxa de produtividade da Enfermagem pode ser calculada pela relação entre horas de assistência prestadas e número de pacientes atendidos.","Indicadores como taxa de ocupação, taxa de infecção e taxa de absenteísmo são utilizados para mensurar aspectos da produção e qualidade da assistência de Enfermagem.","A taxa de infecção relac ionada à assistência à saúde (IRAS) representa um indicador de resultado diretamente ligado à qualidade do cuidado.","A produção de Enfermagem deve ser analisada apenas sob a perspectiva quantitativa, desconsiderando aspectos qualitativos do cuidado prestado"],"gabarito":"E"},{"n":39,"disciplina":"Enfermagem","assunto":"Saúde da Criança e do Adolescente","enunciado":"Com a intenção de atuar sobre a obesidade infantil, a Secretaria de Saúde do Município Beta estabeleceu um conjunto de ações e indicadores, dentre eles: taxa de crianças menores de 6 meses, em aleitamento exclusivo; prevalência de obesidade infantojuvenil em crianças menores de 2 anos, nos últimos 10 anos; e taxa de adesão ao protocolo de aconselhamento sobre aleitamento exclusivo, pela equipe de Enfermagem. Os indicadores de qualidade da assistência de Enfermagem avaliam a eficiência e a segurança do cuidado, sendo classificados em indicadores de impacto, de processo e de resultado. Os exemplos citados tratam -se, respectivamente, de indicadores de","alternativas":["resultado, impacto e processo.","impacto, resultado e processo.","processo, resultado e impacto.","impacto, processo e resultado.","resultado, processo e impacto"],"gabarito":"A"},{"n":40,"disciplina":"Enfermagem","assunto":"Gestão em Enfermagem","enunciado":"O parecer normativo 1/2024 do COFEN, que cria parâmetros para o planejamento da força de trabalho da Enfermagem pelo enfermeiro, apresenta a seguinte equação para cálculo em Instituições Hospitalares e Unidade de Internação em Hospitais Gerais: Sendo: Assinale a opção que apresenta o significado correto da sigla IST na equação:","alternativas":["infecções sexualmente transmissíveis.","indicador de segurança do trabalho.","índice de segurança do trabalho.","índice de segurança técnica.","indicador de sazonalidade no trabalho."],"gabarito":"D"}]},{"id":"ni2025-fiscal-enfermagem","cargo":"Fiscal Sanitário — Enfermagem","prova":"https://conhecimento.fgv.br/sites/default/files/concursos/fiscal-sanitario-enfermagem-cns010-tipo-1.pdf","gabarito":"https://conhecimento.fgv.br/sites/default/files/concursos/gabarito-definitivo-smsnovaiguacu.pdf","itens":[{"n":16,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"De acordo com a legislação, o Sistema Nacional de Vigilância Sanitária (SNVS) é definido como","alternativas":["o conjunto de ações executado por instituições da Administração Pública direta e indireta da União, dos Estados, do Distrito Federal e dos Municípios, que exerçam atividades de regulação, controle e fiscalização, articuladas com os serviços de assistência clínica e hospitalar previstos nos arts. 19 a 24 da Lei nº 8.080/90.","o conjunto de ações de vigilância sanitária definido pelo § 1º do art. 6º da Lei nº 8.080, de 19 de s etembro de 1990, executado exclusivamente por instituições da Administração Pública federal, cabendo à Agência Nacional de Vigilância Sanitária a coordenação e execução de todas as atividades de regulação, normatização, controle e fiscalização sanitária no território nacional.","o conjunto de ações definido pelo § 1º do art. 6º e pelos arts. 15 a 18 da Lei nº 8.080, de 19 de setembro de 1990, executado por instituições da Administração Pública direta e indireta da União, dos Estados, do Distrito Federal e dos Municípios, que exerçam atividades de regulação, normatização, controle e fiscalização na área de vigilância sanitária.","o conjunto de ações de regulação sanitária previsto nos arts. 6º a 8º da Lei nº 9.782, de 26 de janeiro de 1999, executado por instituições da Administração Pública direta e indireta, limitado ao registro, controle e fiscalização de produtos e serviços de interesse para a saúde, incluindo medicamentos, alimentos, cosméticos e saneantes, sob coordenação exclusiva da Agência Nacional de Vigilância Sanitária.","o conjunto de ações organizadas em caráter complementar às atividades de Atenção Básica, com foco no monitoramento clínico-epidemiológico da população atendida no SUS"],"gabarito":"C"},{"n":17,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"Sobre as infrações sanitárias e suas sanções, conforme a Lei nº 6.437/1977, analise as afirmativas a seguir. I. As infrações sanitárias independem da intenção do infrator, bastando a prática do ato irregular. II. Entre as sanções aplicáveis, estão advertência, multa, interdição e cancelamento de autorização. III. Para caracterização da infração sanitária, é indispensável a comprovação de dolo ou má-fé. Está correto o que se afirma em","alternativas":["I, apenas.","II, apenas.","I e II, apenas.","II e III, apenas.","I, II e III."],"gabarito":"C"},{"n":18,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"Durante inspeção em uma drogaria, a Vigilância Sanitária municipal constatou a venda de medicamentos controlados sem retenção da receita. O fiscal lavrou auto de infração e aplicou medida cautelar de interdição parcial. O responsável técnico apresentou defesa administrativa no prazo legal. Nesse caso, a conduta do fiscal encontra respaldo no processo administrativo-sanitário, assegurando ao infrator o direito ao","alternativas":["julgamento célere, cujo recurso administrativo terá efeito suspensivo automático da penalidade.","contraditório e à ampla defesa, previstos em lei.","recurso exclusivo à instância judicial.","arquivamento do auto de infração, desde que o responsável técnico desfaça a irregularidade.","afastamento automático da penalidade mediante alegação de boa-fé"],"gabarito":"B"},{"n":19,"disciplina":"Direito Administrativo","assunto":"Poderes Administrativos","enunciado":"No que se refere ao poder de polícia administrativa sanitária, classifique as afirmativas como verdadeira (V) ou falsa (F). ( ) A fiscalização sanitária pode aplicar medidas preventivas, mesmo sem autorização judicial, desde que haja previsão legal. ( ) A autoexecutoriedade permite que a Administração cumpra diretamente seus atos, sem necessidade de ordem judicial prévia, quando houver urgência ou autorização legal. ( ) A coercibilidade do poder de polícia autoriza o uso ilimitado da força estatal, indepe ndentemente dos princípios constitucionais da legalidade e proporcionalidade. As afirmativas são, respectivamente,","alternativas":["V – V – F.","V – F – V.","F – V – V.","V – V – V.","F – F – V"],"gabarito":"A"},{"n":20,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"A Lei nº 8.080/1990 organiza as ações os serviços de saúde no SUS e define, entre suas atribuições, a vigilância epidemiológica, fundamental para identificar e controlar agravos à saúde pública no território. Segundo a Lei nº 8.080/1990, a vigilância epidemiológica é definida como","alternativas":["conjunto de ações que proporciona conhecimento, detecção ou prevenção de mudanças nos fatores determinantes e condicionantes da saúde, visando recomendar e adotar medidas de prevenção e controle.","atividade restrita ao diagnóstico clínico de doenças transmissíveis em território nacional.","conjunto de ações capaz de eliminar, diminuir ou prevenir riscos à saúde e de intervir nos problemas sanitários decorrentes do meio ambiente, da produção e circulação de bens e da prestação de serviços.","conjunto de atividades que se d estina, através de ações de vigilância, à promoção e proteção da saúde dos trabalhadores, visando a recuperação e reabilitação da saúde dos que sofrem agravos no trabalho.","ação privativa da União, sem participação de Estados e Municípios"],"gabarito":"A"},{"n":21,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"Em Nova Ig uaçu, a Vigilância Sanitária Municipal recebeu denúncias da comunidade sobre descarga irregular de efluentes por uma indústria de produtos de higiene localizada próxima a uma escola. Em inspeção, a equipe constatou risco sanitário relevante. O fiscal lavro u auto de infração, expediu termo de interdição parcial da linha produtiva envolvida e apreendeu lotes suspeitos para análise. O fato foi comunicado ao Conselho Municipal de Saúde, em razão das denúncias reiteradas e do potencial impacto no território. A e mpresa apresentou defesa administrativa no prazo legal, alegando boa-fé e ausência de dolo. À luz da legislação sanitária aplicável e das competências municipais no SNVS, assinale a opção correta quanto à atuação da Vigilância Sanitária Municipal de Nova Iguaçu.","alternativas":["As medidas cautelares são inválidas sem prévia autorização judicial; ademais, por envolver efluentes, a competência para interdição é exclusiva do órgão ambiental estadual.","A interdição cautelar parcial, o auto de infração e a apreensão são atos válidos de polícia sanitária municipal; a responsabilidade administrativa independe de dolo; e a comunicação ao Conselho Municipal de Saúde reforça o controle social.","A aplicação de sanções exige prova de má -fé do infrator; a interdição somente pode ser decretada por decisão colegiada da Anvisa; e o Conselho Municipal de Saúde não possui função consultiva nesse tipo de ocorrência.","O processo administrativo -sanitário deve ser instaurado, porém a alegação de boa-fé extingue a penalidade; além disso, denúncias populares não podem fundamentar a ação fiscal sem laudo judicial prévio.","Por se tratar de risco coletivo, a Vigilância Sanitária municipal deve aguardar determinação do Ministério Público; a ampla defesa e o contraditório só se aplicam na esfera judicial"],"gabarito":"B"},{"n":22,"disciplina":"Legislação do SUS","assunto":"Controle Social no SUS","enunciado":"Sobre a participação social no SUS e sua interface com a Vigilância em Saúde, analise as assertivas a seguir: I. O Conselho Municipal de Saúde é órgão colegiado permanente e deliberativo, composto por representantes do governo, dos prestadores de serviços, dos profissionais de saúde e dos usuários. II. As deliberações do Conselho Municipal de Saúde, embora tenham caráter consultivo, não produzem efeitos obrigatórios para o gestor local do SUS. III. As conferências de saúde, convocadas a cada quatro anos, com representação dos vários segmentos sociais, destinam -se a avaliar a situação de saúde e propor diretrizes para as políticas de saúde, inclusive de vigilância. Está correto o que se afirma em","alternativas":["I, apenas.","II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III."],"gabarito":"C"},{"n":23,"disciplina":"Legislação do SUS","assunto":"Controle Social no SUS","enunciado":"O município de Nova Iguaçu se prepara para realizar sua Conferência Municipal de Saúde. Entre as discussões, incluem -se propostas da comunidade sobre fiscalização sanitária de indústrias locais, ações de vigilância epidemiológica no território e diretrizes para maior integração da Atenção Básica com a vigilância em saúde. De acordo com a Lei nº 8.142/1990, a Conferência de Saúde tem como atribuição principal","alternativas":["avaliar a situação de saúde e propor dire trizes para a formulação da política de saúde, convocada a cada quatro anos, com representação de vários segmentos sociais.","substituir o Conselho Municipal de Saúde em sua função deliberativa permanente, sempre que ocorrer risco sanitário relevante.","exercer poder de polícia administrativa sobre os estabelecimentos de saúde e indústria de interesse sanitário.","atuar como órgão fiscalizador da gestão financeira do Fundo Municipal de Saúde, com competência para aplicar sanções a gestores.","homologar diretamente as deliberações das conferências estaduais, garantindo sua aplicação automática no município"],"gabarito":"A"},{"n":24,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"Uma ESF identificou aumento de casos de diarreia em sua área, notificou a Vigilância Epidemiológica municipal, que investigou o surto e articulou ações com outros setores. Sobre a integração entre Vigilância em Saúde e Atenção Primária, está correto afirmar que a","alternativas":["notificação deveria ter sido feita diretamente ao nível estadual, por tratar -se de surto de notificação compulsória imediata.","Vigilância Epidemiológica atua independentemente da Atenção Primária, pois possuem fluxos assistenciais distintos.","identificação pela APS, investigação epidemiológica e articulação intersetorial exemplificam a integração territorial entre cuidado e vigilância.","participação do Conselho Municipal de Saúde constitui ingerência indevida na gestão técnico -operacional da vigilância.","integração entre APS e Vigilância em Saúde depende da decisão da gestão municipal"],"gabarito":"C"},{"n":25,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"A atuação da Vigilância Sanitária Municipal pode ser planejada de forma tradicional (resposta a denúncias) ou por meio da fiscalização orientada por risco e da vigilância ativa, princípios reforçados nas políticas nacionais de saúde. A fiscalização orientada por risco na Vigil ância Sanitária caracteriza-se por","alternativas":["selecionar previamente os alvos de inspeção com base em critérios técnicos de gravidade, probabilidade e impacto dos riscos sanitários.","priorizar estabelecimentos com maior histórico de não - conformidades identific adas em inspeções anteriores, independentemente da análise prospectiva de gravidade do dano potencial à saúde.","atuar apenas em resposta a denúncias da comunidade, sem planejamento prévio.","concentrar ações em estabelecimentos de alta complexidade, como hospitais e laboratórios, por apresentarem risco sanitário inerente.","depender de autorização judicial para cada ação de fiscalização preventiva"],"gabarito":"A"},{"n":26,"disciplina":"Direito Administrativo","assunto":"Poderes Administrativos","enunciado":"O poder de polícia administrativa sanitária permite que o fiscal municipal limite ou condicione ativ idades privadas em prol da saúde coletiva. No entanto, a Constituição Federal e a legislação em vigor impõem limites a esse poder, vedando arbitrariedades e responsabilizando a autoridade que ultrapassar tais limites. Configura abuso de autoridade, no exer cício do poder de polícia sanitária, quando o fiscal","alternativas":["interdita preventivamente um estabelecimento sem autorização prévia do gestor municipal, fundamentando -se exclusivamente em risco sanitário grave e iminente constatado em inspeção.","recusa-se a liberar alvará sanitário mesmo após regularização das não-conformidades, até que o estabelecimento comprove quitação de multas anteriores.","apreende produtos vencidos e aplica multa no mesmo ato de inspeção, sem conceder prazo prévio para defesa ou regularização voluntária.","utiliza o cargo para constranger indevidamente o administrado, aplicando sanção não prevista em lei.","realiza inspeção programada em estabelecimento de interesse à saúde, com base em plano municipal de vigilância"],"gabarito":"D"},{"n":27,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"A respeito da integração da Vigilância em Saúde com o SUS no território, assinale a opção incorreta.","alternativas":["A Atenção Primária à Saúde é porta de entrada preferencial do SUS e deve articular -se continuamente com a Vigilância em Saúde.","A vigilância ativa pressupõe busca de casos e monitoramento proativo, evitando depender exclusivamente de notificações espontâneas.","A fiscalização orientada por risco deve priorizar recursos em áreas e serviços de maior impacto sanitário, aumentando a eficiência do controle.","A participação da comunidade é facultativa, não havendo obrigatoriedade de mecanismos institucionais de controle social na vigilância.","A integração entre APS e vigilância contribui para superar a fragmentação entre promoção, prevenção e cuidado clínico."],"gabarito":"D"},{"n":28,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"Considerando a legislação sanitária federal, o Sistema Nacional de Vigilância Sanitária (SNVS) e os princípios do SUS, assinale a opção incorreta.","alternativas":["O SNVS, definido pela Lei nº 9.782/1999, integra instituições das três esf eras de governo que exercem atividades de regulação, controle e fiscalização sanitária.","O auto de infração e o termo de apreensão podem ser lavrados no mesmo ato fiscalizatório, sendo que a apreensão independe de defesa prévia quando houver risco sanit ário, mas a sanção pecuniária exige processo administrativo.","O poder de polícia sanitária permite impor restrições à atividade econômica, devendo sempre respeitar os princípios da legalidade, proporcionalidade e motivação.","A fiscalização orientada por risco e a vigilância ativa dispensam a participação comunitária, pois são de competência exclusiva da autoridade sanitária.","A notificação de doenças pela APS à Vigilância Epidemiológica pode ser compulsória para alguns agravos e facultativa para outros, conforme definido em lista nacional atualizada periodicamente pelo Ministério da Saúde"],"gabarito":"D"},{"n":29,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"A Política Nacional de Vigilância em Saúde (PNVS) é uma política pública de Estado e função essencial do SUS, tendo caráter universal, transversal e orientador do modelo de atenção nos territórios, sendo a sua gestão de responsabilidade exclusiva do poder público. Sobre os termos definidos na PNVS, analise os itens a seguir. I. Modelo de Atenção à Saúde: um conjunto articulado de ações e serviços preventivos e curativos, individuais e coletivos, exigidos para cada caso em todos os níveis de complexidade do sistema. Deve compreender o acesso às ações, aos serviços e aos produtos seguros e eficazes, indispensáveis para as necessidades de saúde da população, objetivando promover a qualidade de vida e reduzir a vulnerabilidade e os riscos à saúde relacionados aos seus determinantes e condicionantes. II. Linha de Cuidado (LC): uma forma de articulação de recursos e das práticas de produção de saúde, orientadas por dir etrizes clínicas, entre as Unidades de Atenção de uma dada região de saúde, para a condução oportuna, ágil e singular, dos usuários pelas possibilidades de diagnóstico e terapia, em resposta às necessidades epidemiológicas de maior relevância. III. Rede de Atenção à Saúde: arranjos organizativos de ações e serviços de saúde, de diferentes densidades tecnológicas, que integradas por meio de sistemas técnico, logístico e de gestão, buscam garantir a integralidade do cuidado. Está correto o que se afirma em","alternativas":["I, II e III.","II e III, apenas.","I e II, apenas.","III, apenas.","I e III, apenas"],"gabarito":"B"},{"n":30,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"Os processos de avaliação do risco sanitário podem ser realizados utilizando-se diversas ferramentas (ou técnicas) de apoio ao gerenciamento de risco. A ferramenta que identifica caso todas as formas possíveis de componentes, processos ou sistemas falhem, bem como os efeitos potenciais das falhas e quais os mecanismos de falha, e como evitar ou mitigar os efeitos delas no sistema, é conhecida como","alternativas":["análise BOW TIE.","análise FMEA.","análise de causa raiz.","matriz de risco.","matriz GUT"],"gabarito":"B"},{"n":31,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"Sobre as Boas Práticas de Manipulação de Alimentos (BPM), analise os itens a seguir. I. As operações de limpeza e, se for o caso, de desinfecção das instalações e equipamentos, quando não forem realizadas rotineiramente, devem ser registradas. II. A área de preparação do alimento deve ser higienizada duas vezes ao dia, antes do início e imediatamente após o término do trabalho. Devem ser tomadas precauções para impedir a contaminação dos alimentos causada por produtos saneantes, pela suspensão de partículas e pela formação de aerossóis. III. Os funcionários responsáveis pela atividade de recebimento de dinheiro, cartões e outros meios utilizados para o pagamento de despesas podem manipular alimentos preparados, desde que estejam embalados. Está correto o que se afirma em","alternativas":["I, apenas.","II, apenas.","III, apenas.","I e II, apenas.","I, II e III"],"gabarito":"A"},{"n":32,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"A partir da suspeita de ocorrência de um surto de Doenças Transmitidas por Alimentos (DTA), a equipe de vigilância sanitária deve I. promover inspeções nas diversas etapas da cadeia alimentar; II. orientar a intervenção, objetivando a prevenção de agravos à saúde do consumidor no que se refere às questões sanitárias, inclusive quanto ao teor nutricional; III. identificar a possibilidade de sobrevivência, proliferação de alguns micro-organismos e/ou inativação de toxinas. Está correto o que se afirma em","alternativas":["I, apenas.","II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III."],"gabarito":"E"},{"n":33,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"A gestão de riscos relativa às emergências em saúde pública por desastres compreende a atuação em distintas fases. Promover a cooperação o intercâmbio técnico -científico com organizações governamentais e não governamentais, de âmbito nacional e internacional, na gestão de riscos quanto aos desastres em emergências na saúde pública, representa uma ação de","alternativas":["preparação.","monitoramento.","alerta.","comunicação.","resposta. Vigilância Sanitária - Enfermagem"],"gabarito":"A"},{"n":34,"disciplina":"Enfermagem","assunto":"Ética e Legislação em Enfermagem","enunciado":"O Enfermeiro Responsável Técnico (ERT) possui atribuições específicas. Não se configura como uma de suas responsabilidades","alternativas":["a função de elaboração, adequação e supervisão da escala de serviço da Enfermagem, por setor, fixando-a em local visível.","a garantia de que a assistência de Enfermagem a pacientes em estado grave seja prestada exclusivamente por enfermeiros e técnicos de Enfermagem habilitados.","a assunção da responsabilidade exclusiva pela condução de processos de seleção, admissão e desligamento de profissionais de Enfermagem.","a comunicação, de ofício, ao Coren e ao responsável legal da instituição, sobre qualquer indício de infração à legislação do exercício profissional, como o déficit de profissionais.","o afastamento preventivo de profissionais da equipe, em situação ilegal ou com impedimento ético-legal, comunicando o fato ao Coren e à administração da instituição"],"gabarito":"C"},{"n":35,"disciplina":"Enfermagem","assunto":"Segurança do Paciente","enunciado":"O protocolo de identificação do paciente, integrante do Programa Nacional de Segurança do Paciente (PNSP), tem como objetivo reduzir a ocorrência de erros relacionados à assistência em saúde. Sobre esse protocolo, é incorreto afirmar que","alternativas":["a identif icação do paciente deve ser realizada utilizando, no mínimo, dois identificadores, como nome completo e data de nascimento.","a pulseira de identificação é um dos recursos recomendados, devendo estar legível e íntegra.","a identificação deve ser checad a antes da administração de medicamentos, realização de exames, procedimentos invasivos e cirurgias.","a identificação e a conferência do paciente são de responsabilidade exclusiva do setor de admissão.","a padronização da identificação é fundamental para reduzir riscos de trocas de pacientes e garantir a segurança em todas as etapas do cuidado."],"gabarito":"D"},{"n":36,"disciplina":"Enfermagem","assunto":"Controle de Infecção e Biossegurança","enunciado":"A Comissão de Controle de Infecção Hospitalar (CCIH) constitui um órgão de assessoria vinculado à autoridade máxima da instituição de saúde, sen do formada por profissionais de saúde de nível superior, distribuídos em duas categorias: membros consultores e membros executores. Sobre a CCIH, analise as afirmativas a seguir. I. Os membros consultores deverão ser representantes do serviço médico, de E nfermagem, Farmácia, Microbiologia, Administração, entre outros serviços relevantes dentro de cada instituição. II. Para hospitais com até 70 leitos, somente enfermeiros são obrigatórios entre os membros consultores. III. Os membros executores representam o Serviço de Controle de Infecção Hospitalar (SCIH) e são os encarregados pelas ações do Serviço. IV. Entre os membros executores, a instituição deverá contar com, no mínimo, dois técnicos de nível superior da área de saúde para cada 200 leitos, e um dos m embros deve ser, preferencialmente, um médico ou um enfermeiro. Está correto o que se afirma em","alternativas":["I, apenas.","II, apenas.","III e IV, apenas.","II e IV, apenas.","I e III, apenas"],"gabarito":"E"},{"n":37,"disciplina":"Enfermagem","assunto":"Gerenciamento de Resíduos de Serviços de Saúde (GRSS)","enunciado":"De acordo com a RDC/ANVISA nº 222/2018, os estabelecimentos geradores de resíduos de serviços de saúde (RSS) são responsáveis pelo correto gerenciamento de todos os resíduos por eles produzidos. Todo serviço gerador deve dispor de um Plano de Gerenciament o de RSS (PGRSS), observando as regulamentações federais, estaduais, municipais ou do Distrito Federal, exceto,","alternativas":["serviços que geram resíduos do Grupo B.","serviços que geram resíduos do Grupo A.","serviços que possuem instalação radiativa.","serviços que geram exclusivamente resíduos do Grupo D.","serviços que geram resíduos dos Grupos A e D"],"gabarito":"D"},{"n":38,"disciplina":"Enfermagem","assunto":"Processo de Enfermagem e SAE","enunciado":"A documentação do Processo de Enfermagem deve ser realizada pelos membros da equipe formalmente no prontuário do paciente, físico ou eletrônico. O registro das etapas do processo de Enfermagem no prontuário do paciente é imprescindível ao processo do cuidar. São finalidades dos registros de Enfermagem, exceto","alternativas":["da partilha de informações.","da evidência legal.","de ensino e pesquisa.","de auditoria.","de comunicação com familiares"],"gabarito":"E"},{"n":39,"disciplina":"Enfermagem","assunto":"Ética e Legislação em Enfermagem","enunciado":"A fiscalização dos procedimentos de Enfermagem constitui instrumento essencial para garantir a segurança do paciente e a qualidade da assistência prestada. Nesse processo, avalia -se a conformidade das práticas , como, por exemplo, a administração de medicamentos, em relação às boas práticas e às normas técnicas vigentes. Considerando esse contexto, é incorreto afirmar que","alternativas":["a fiscalização deve priorizar exclusivamente os aspectos técnicos dos procedimentos, não cabendo avaliar aspectos relacionais ou comunicacionais da assistência.","a fiscalização deve verificar se a administração de medicamentos segue as normas estabelecidas para preparo, checagem e registro adequado no prontuário.","na t erapia infusional, a conformidade inclui avaliação do acesso venoso, controle do tempo de infusão, integridade do dispositivo e prevenção de complicações.","a inspeção de cateteres deve considerar o registro do procedimento, tempo da punção, avaliação do local do acesso e descarte adequado dos materiais.","o processo fiscalizatório deve estar pautado em referenciais legais, normativos e científicos, assegurando a uniformidade e a qualidade da prática assistencial"],"gabarito":"A"}]},{"id":"ni2025-planejamento","cargo":"Analista Técnico em Planejamento de Serviços de Saúde","prova":"https://conhecimento.fgv.br/sites/default/files/concursos/analista-tecnico-em-planejamento-de-servicos-de-saude-cns001-tipo-1.pdf","gabarito":"https://conhecimento.fgv.br/sites/default/files/concursos/gabarito-definitivo-smsnovaiguacu.pdf","itens":[{"n":7,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Regra de Três e Problemas Aritméticos","enunciado":"A dosagem máxima diária de um medicam ento administrável a uma pessoa em tratamento é calculada a partir da proporção de 4 gotas para cada 1,5 kg de sua massa corporal. O número de gotas desse medicamento que compõe a dosagem máxima administrável a uma pessoa com 75 kg, é de","alternativas":["300.","200.","150.","100.","50"],"gabarito":"B"},{"n":10,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Análise Combinatória","enunciado":"O setor de Emergência de um hospital monta as suas equipes plantonistas com especialistas nas áreas de Obstetrícia, Pneumologia, Cardiologia e Ortopedia. O quadro de plantonistas conta com 5 especialistas de cada área e as equipes plantonistas são montadas com 2 especialistas de cada área. O número máximo de equipes planton istas distintas, que podem ser montadas, é","alternativas":["10 000.","1 250.","625.","40.","25."],"gabarito":"A"},{"n":12,"disciplina":"Legislação do SUS","assunto":"Lei 8.080/1990 - Princípios e Diretrizes","enunciado":"Em uma Unidade de Saúd e foi priorizado o atendimento de um idoso com múltiplas comorbidades, enquanto outros usuários aguardavam. Essa decisão foi justificada pela equipe como forma de atender às maiores necessidades em saúde. O princípio do SUS que justifica a decisão da equipe é o de","alternativas":["universalidade.","equidade.","integralidade.","regionalização.","participação social"],"gabarito":"B"},{"n":13,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"Uma forte chuva ocorrida em região urbana resultou em inundações em diferentes bairros da cidade, causando a interrupção de serviços essenciais. Após as enchentes, houve um aumento de casos de leptospirose e de doenças respiratórias, além de relatos de aci dentes de trabalho e preocupações ambientais relacionadas à qualidade do ar e ao lixo acumulado. Considerando esse contexto, analise os itens a seguir. I. A vigilância epidemiológica contribuirá para monitorar a incidência de doenças transmissíveis e dete ctar rapidamente novos casos que possam surgir após o desastre. II. A vigilância sanitária será importante na fiscalização do abastecimento de água e alimentos, além de garantir o cumprimento de normas de higiene e segurança das estruturas públicas e privadas afetadas. III. A vigilância em saúde ambiental se encarregará de identificar fatores de risco relacionados à qualidade do ar, ao acúmulo de lixo e às condições do solo e da água, promovendo ações de controle e mitigação. Está correto o que se afirma em","alternativas":["I e II, apenas.","III, apenas.","I e III, apenas.","II e III, apenas.","I, II e III"],"gabarito":"E"},{"n":14,"disciplina":"Enfermagem","assunto":"Imunização","enunciado":"Em março de 2025, a Prefeitura de Nova Iguaçu promoveu vacinação itinerante contra a influenza, com o “Ônibus da Saúde” percorrendo locais d e grande circulação, das 8h às 14h. Além da vacina contra a gripe, foram oferecidas vacinas de rotina, como sarampo e Covid-19. Fonte: Prefeitura de Nova Iguaçu (31/03/2025). A iniciativa amplia o acesso da população às vacinas e complementa o trabalho das unidades básicas de saúde. Analise as afirmativas a seguir e classifique -as como verdadeiras (V) ou falsas (F). ( ) A vacinação itinerante exemplifica a universalidade do SUS e a PNAB, que organiza as ações de imunização na Atenção Básica. ( ) A iniciativa assegura universalidade e integralidade ao oferecer acesso irrestrito e cuidado contínuo. ( ) Com a CF/88 e a Lei nº 8.080/1990, a saúde passou a ser direito universal e dever do Estado, incluindo a vacinação na Atenção Básica. ( ) A vacinação itinerante, com apoio das equipes da ESF, demonstra integração entre Vigilância Epidemiológica e PNAB. As afirmativas são, respectivamente:","alternativas":["V – V – V – F.","V – V – V – V.","F – V – V – F.","V – V – F – V.","V – F – V – F."],"gabarito":"E"},{"n":15,"disciplina":"Legislação do SUS","assunto":"Redes de Atenção à Saúde","enunciado":"Em agosto de 2025, a Prefeitura de Nova Iguaçu realizou mutirão com atendimentos especializados e vacinação, pelo programa federal “Agora Tem Especialistas”, aplicando a metodologia de Oferta de Cuidados Integrados (OCI), que reúne consultas, exames e diagnóstico em um único fluxo. Fonte: Prefeitura de Nova Iguaçu (09/08/2025). A OCI integra procedimentos clínicos, diagnósticos e de gestão, fortalecendo a Atenção Básica e promovendo cuidado contínuo no território. Analise as afirmativas a se guir e classifique -as como verdadeiras (V) ou falsas (F): ( ) A metodologia de Oferta de Cuidados Integrados fortalece a Atenção Primária e o atributo da longitudinalidade da PNAB. ( ) O financiamento do SUS é tripartite, envolvendo União, estados e municípios. ( ) A OCI expressa o princípio da integralidade e reforça a continuidade do cuidado no território. ( ) A PNAB define a imunização e o cuidado oncológico como atribuições exclusivas da atenção especializada. As afirmativas são, respectivamente","alternativas":["V – F – V – F.","F – V – V – F.","V – V – F – V.","V – V – V – V.","V – V – V – F. Planejamento e Gestão em Saúde Pública"],"gabarito":"E"},{"n":16,"disciplina":"Legislação do SUS","assunto":"Constituição Federal - Saúde","enunciado":"A Constituição Federal de 1988 estabelece que a saúde é um direito social, ao lado de outros direitos fundamentais que asseguram a cidadania e a dignidade humana. Entre os direitos sociais expressamente previstos no art. 6º, encontram-se","alternativas":["transporte, lazer e proteção à infância.","comércio, livre iniciativa e defesa do consumidor.","diplomacia, defesa nacional e proteção ambiental.","segurança pública, defesa civil e seguridade nacional.","regime tributário, comunicação social e inovação tecnológica"],"gabarito":"A"},{"n":17,"disciplina":"Legislação do SUS","assunto":"Constituição Federal - Saúde","enunciado":"A Constituição Federal de 1988 define competências comuns entre União, Estados, Distrito Federal e Municípios. Entre essas competências, no que se refere à saúde, estabelece que","alternativas":["apenas os Estados podem organizar e executar ações de saúde pública em seus territórios.","compete somente aos Municípios a proteção da saúde pública, em razão da proximidade com a população.","a saúde é responsabilidade privativa da União, dos Estados e do Distrito Federal, sem participação municipal.","cabe exclusivamente à União cuidar da saúde e da assistência pública, sendo os demais entes apenas executores de políticas federais.","todos os entes federativos devem cuidar da saúde pública, bem como da proteção e garantia das pessoas com deficiência"],"gabarito":"E"},{"n":18,"disciplina":"Direito Administrativo","assunto":"Organização Administrativa","enunciado":"De acordo com a Constituição Federal de 1988, entre as competências dos Municípios está a de","alternativas":["organizar o SUS em todo o território nacional, inclusive em âmbito estadual e federal.","editar normas gerais sobre vigilância sanitária, cabendo aos Estados a execução.","legislar sobre saúde pública em caráter exclusivo, sem participação da União e dos Estados.","prestar, com a cooperação técnica e financeira da União e do Estado, serviços de atendimento à saúde da população.","definir de forma autônoma a distribuição de recursos do Fundo Nacional de Saúde, sem necessidade de cooperação federativa"],"gabarito":"D"},{"n":19,"disciplina":"Legislação do SUS","assunto":"Constituição Federal - Saúde","enunciado":"O art. 196 da Constituição Federal de 1988 estabelece as bases do Sistema Único de Saúde (SUS). De acordo com esse dispositivo,","alternativas":["a saúde pública limita-se à prestação de serviços de emergência e de caráter hospitalar.","a saúde é direito de todos e dever do Estado, assegurado por meio de políticas sociais e econômicas.","a saúde é dever exclusivo da União, não sendo responsabilidade dos Estados e Municípios.","a saúde é direito restrito aos trabalhadores formais e seus dependentes, garantido pelo regime previdenciário.","o acesso à saúde deve ser universal, mas não necessariamente igualitário, podendo variar conforme a renda do cidadão"],"gabarito":"B"},{"n":20,"disciplina":"Legislação do SUS","assunto":"Lei 8.080/1990 - Organização e Competências","enunciado":"De acordo com o art. 200 da Constituição Federal de 1988, compete ao Sistema Único de Saúde (SUS)","alternativas":["supervisionar o processo eleitoral e a organização dos partidos políticos.","organizar a política econômica nacional, definindo diretrizes sobre juros e inflação.","incrementar, em sua área de atuação, o desenvolvimento científico e tecnológico e a inovação.","regular exclusivamente as políticas de defesa nacional, compreendendo a gestão de fronteiras.","coordenar a formulação da política nacional de assistência social, incluindo benefícios eventuais e permanentes"],"gabarito":"C"},{"n":21,"disciplina":"Direito Administrativo","assunto":"Controle da Administração Pública","enunciado":"A Emenda Constitucional nº 109/2021 incluiu o §16 ao art. 37 da Constituição Federal, estabelecendo que órgãos e entidades da administração pública devem realizar avaliação das políticas públicas, com divulgação do objeto e dos resultados alcançados. Essa exigência reforça, de modo especial, o princípio da","alternativas":["legalidade, ao autorizar a administração nos limites da lei.","eficiência, ao suprimir a necessidade de avaliação de resultados.","impessoalidade, ao garantir que o gestor atue em benefício próprio.","moralidade, ao permitir que resultados sejam omitidos em casos excepcionais.","publicidade, ao assegurar a transparência dos resultados das políticas públicas."],"gabarito":"E"},{"n":22,"disciplina":"Direito Administrativo","assunto":"Licitações e Contratos","enunciado":"Na fase preparatória das contratações públicas, a Lei nº 14.133/2021 prevê a elaboração do Estudo Técnico Preliminar (ETP). Esse documento tem como finalidade principal","alternativas":["servir de base para o anteprojeto, termo de referência ou projeto básico.","definir as penalidades aplicáveis ao contratado em caso de descumprimento.","regular prazos de entrega, condições de pagamento e garantias do ajuste.","substituir o contrato administrativo, dispensando a etapa de execução e fiscalização.","apoiar a análise de hipóteses de contratação direta, indicando elementos para a decisão administrativa"],"gabarito":"A"},{"n":23,"disciplina":"Direito Administrativo","assunto":"Licitações e Contratos","enunciado":"Na fase preparatória das licitações, o termo de referência é documento essencial para a contratação de bens e serviços. Entre os elementos que devem constar obrigatoriamente nesse documento, segundo a Lei nº 14.133/2021, está","alternativas":["a definição do objeto, incluindo natureza, quantitativos e prazo do contrato.","a indicação do agente público responsável pela homologação do certame licitatório.","o relatório de auditoria independente sobre a regularidade da execução financeira.","a descrição das penalidades aplicáveis ao contratado por inadimplemento contratual.","a autorização para o pagamento antecipado ao fornecedor antes da assinatura contratual"],"gabarito":"A"},{"n":24,"disciplina":"Legislação do SUS","assunto":"Atenção Primária e PNAB","enunciado":"A Prefeitura de Nova Iguaçu elaborou o Plano Municipal de Saúde (PMS) 2022-2025 como instrumento central de planejamento em saúde, definindo compromissos e diretrizes da gestão municipal do SUS. Nesse contexto, sobre os instrumentos de planejamento do SUS, é correto afirmar que","alternativas":["o Plano Municipal de Saúde é um instrumento de curto prazo, atualizado anualmente por meio do Relatório Anual de Gestão.","o Relatório Anual de Gestão (RAG) substitui a Programação Anual de Saúde, dispensando a necessidade de planejamento anual.","a Programação Anual de Saúde (PAS) traduz as metas e ações definidas no Plano Municipal de Saúde para cada exercício, vinculando-se ao orçamento.","o Relatório Anual de Gestão é facultativo e elaborado majoritariamente em situações de descumprimento das metas estabelecidas no Plano Municipal de Saúde.","a elaboração do Plano Municipal de Saúde compete exclusivamente à União, sendo os municípios responsáveis pela execução operacional das ações previstas"],"gabarito":"C"},{"n":25,"disciplina":"Legislação do SUS","assunto":"Atenção Primária e PNAB","enunciado":"A territorialização em saúde compreende a demarcação geográfica da área de atuação das equipes, considerando aspectos populacionais, sociais, culturais e econômicos. A utilização de mapas temáticos, a partir desse processo, tem papel estratégico no planejamento em saúde. Nesse sentido, é correto afirmar que esses mapas permitem","alternativas":["padronizar nacionalmente os serviços, suprimindo as especificidades regionais do território.","substituir a participação social no planejamento, dispensando conselhos de saúde e pactuações regionais.","delimitar a análise à quantidade de equipes de saúde, preterindo as características populacionais.","registrar os fluxos financeiros aplicados à saúde, abstendo-se de considerar indicadores epidemiológicos.","visualizar a distribuição espacial de dados, identificar áreas de risco e associar eventos de saúde aos determinantes locais"],"gabarito":"E"},{"n":27,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"A Lei Orgânica da Saúde define a Vigilância Epidemiológica como “um conjunto de ações que proporciona o conhecimento, a detecção ou a prevenção de qualquer mudança nos fatores determinantes e condicionantes de saúde individual ou coletiva, com a finalidade de recomendar e adotar as medidas de prevenção e controle das doenças ou agravos”. O objetivo geral da Vigilância Epidemiológica é","alternativas":["manter as ações necessárias para o controle das doenças imunopreveníveis do Programa Nacional de Imunização (PNI).","implementar a vigilância de agravos não transmissíveis, como acidentes e violências, em articulação com programas e instituições.","coordenar os programas de DST/Aids e hepatites virais, hanseníase, tuberculose, tabagismo e programa de Imunização.","realizar a análise permanente da situação de saúde da população, por meio de ações de proteção, prevenção, controle de doenças e promoção da saúde.","fortalecer a integração das ações de vigilância epidemiológica com as ações de vigilância ambiental em saúde e atenção primária em saúde, por distrito de Saúde."],"gabarito":"D"},{"n":28,"disciplina":"Legislação do SUS","assunto":"Controle Social no SUS","enunciado":"O gestor da saúde pública, responsável por controlar, avaliar e monitorar as ações e serviços de saúde, confronta-se diariamente com processos e atividades que são baseados em informações: Para investigar surtos de dengue e tuberculose, busca um sistema que registre notificações de doenças e agravos. Para avaliar a mortalidade infantil e causas de óbitos, recorre a um sistema que consolide declarações de óbito. Para acompanhar o estado nutricional da população em situação de vulnerabilidade, utiliza um sistema voltado à vigilância alimentar e nutricional. Nessa situação, os sistemas utilizados pela Secretaria Municipal de Saúde de Nova Iguaçu são, respectivamente,","alternativas":["SINAN, SIM e SISVAN.","SIPNI, SISPRENATAL e SIAB.","CNES, SIH/SUS e SIOPS.","SIPNI, CNES e SIAB.","SIM, SIAB e SISPRENATAL"],"gabarito":"A"},{"n":29,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"A gestão do SUS utiliza diferentes sistemas de informação para subsidiar o planejamento, a avaliação e o monitoramento das ações e dos serviços de saúde. O sistema que organiza as informações da Atenção Primária à Saúde, apoiando a gestão municipal e a qualificação do cuidado, é","alternativas":["SIM.","SINAN.","SINASC.","SIH/SUS.","e-SUS APS"],"gabarito":"E"},{"n":30,"disciplina":"Legislação do SUS","assunto":"Redes de Atenção à Saúde","enunciado":"A Rede de Atenção à Saúde (RAS) no SUS tem como diretriz a organização integrada dos serviços em diferentes pontos de atenção, garantindo acesso, continuidade e integralidade do cuidado. No município de Nova Iguaçu, a Atenção Básica desempenha papel central nessa rede. De acordo com a Política Nacional de Atenção Básica (PNAB), a novidade mais recente de 2020 foi a criação das Unidades de Saúde da Família (USF), que se diferenciam das Unidades Básicas de Saúde (UBS), pela exigência de","alternativas":["funcionamento exclusivo em áreas rurais e de difícil acesso.","oferta de serviços especializados de média complexidade, como Cardiologia e Oftalmologia.","atendimento restrito a gestantes, crianças e idosos, em regime de referência e contrarreferência.","composição mínima de uma equipe de Saúde da Família, formada por médico, enfermeiro, auxiliar ou técnico de Enfermagem e agente comunitário de saúde.","estrutura de um equipe multiprofissional, responsável por desenvolver ações integrais de saúde frente às necessidades de pessoas em vulnerabilidade social"],"gabarito":"D"},{"n":31,"disciplina":"Legislação do SUS","assunto":"Redes de Atenção à Saúde","enunciado":"A Rede de Atenção à Saúde (RAS) do município de Nova Iguaçu organiza-se em diferentes níveis de atenção. No que se refere à rede de assistência especializada, analise os itens a seguir, classificando-os como verdadeiro (V) ou falso (F). ( ) O município dispõe de um Centro de Especialidades em Odontologia (CEO), voltado ao atendimento odontológico especializado. ( ) A rede municipal não oferece consultas em especialidades médicas, sendo esse atendimento restrito apenas a hospitais gerais. ( ) O município conta com laboratório municipal, laboratórios contratualizados e ainda com serviços referenciados ao Laboratório Central Noel Nutel (LACEN-RJ). A sequência correta é, respectivamente,","alternativas":["F – V – V.","V – F – V.","V – F – F.","F – V – F.","V – V – F"],"gabarito":"B"},{"n":32,"disciplina":"Direito Administrativo","assunto":"Controle da Administração Pública","enunciado":"O monitoramento, a avaliação e a fiscalização de contratos constituem medidas de defesa do interesse público, garantindo que a execução dos serviços seja acompanhada e ajustada quando necessário. Nesse processo, a Comissão de Acompanhamento tem como atribuição","alternativas":["avaliar a capacidade instalada.","restringir-se à coleta de dados estatísticos.","elaborar parecer jurídico sobre os contratos de gestão.","homologar os relatórios da contratada automaticamente.","atuar de forma paralela e independente da fiscalização"],"gabarito":"A"},{"n":33,"disciplina":"Legislação do SUS","assunto":"Redes de Atenção à Saúde","enunciado":"A avaliação é parte fundamental no planejamento e na gestão do SUS. No que se refere às ações atribuídas à avaliação de serviços e programas de saúde, analise as afirmativas a seguir, classificando- as como verdadeira (V) ou falsa (F). ( ) A avaliação deve contemplar a relação entre programação, produção e faturamento dos serviços. ( ) Faz parte da avaliação a análise da qualidade e da satisfação dos usuários, incluindo aspectos como acessibilidade e resolubilidade. ( ) A avaliação delimita-se à coleta de dados financeiros em detrimento dos impactos epidemiológicos das ações de saúde. As afirmativas são, respectivamente,","alternativas":["F – V – V.","V – F – V.","V – F – F.","F – V – F.","V – V – F."],"gabarito":"E"},{"n":34,"disciplina":"Legislação do SUS","assunto":"Financiamento do SUS e LC 141/2012","enunciado":"Sobre os critérios do Orçamento da Seguridade Social para a transferência de recursos da União aos Estados, Municípios e Distrito Federal, analise os itens a seguir. I. Perfil demográfico da região e epidemiológico da população a ser coberta. II. Características quantitativas e qualitativas da rede de serviços de saúde existente. III. Desempenho técnico, econômico e financeiro no período anterior. Está correto o que se afirma em","alternativas":["I, apenas.","II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III"],"gabarito":"E"},{"n":35,"disciplina":"Legislação do SUS","assunto":"Financiamento do SUS e LC 141/2012","enunciado":"No âmbito do SUS, a execução das políticas públicas de saúde depende da articulação entre planejamento e orçamento, operacionalizada por meio dos instrumentos orçamentários previstos na Constituição Federal de 1988: o Plano Plurianual (PPA), a Lei de Diretrizes Orçamentárias (LDO) e a Lei Orçamentária Anual (LOA). Sobre os instrumentos orçamentários aplicados à área da saúde, analise os itens a seguir. I. O PPA define, para um período de quatro anos, as diretrizes, objetivos e metas da Administração Públi ca, orientando a formulação dos planos de saúde em cada esfera de governo. II. A LOA estabelece as metas e prioridades da Administração Pública para o exercício financeiro subsequente, orientando a elaboração da LDO e compatibilizando o planejamento com a execução orçamentária anual. III. A LDO detalha as ações e os programas que serão executados no respectivo exercício, definindo os recursos destinados à saúde e viabilizando financeiramente as metas estabelecidas no PPA e priorizadas pela LOA. Está correto o que se afirma em","alternativas":["I, apenas.","II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III"],"gabarito":"A"},{"n":36,"disciplina":"Legislação do SUS","assunto":"Financiamento do SUS e LC 141/2012","enunciado":"A Lei Complementar nº 141/2012 estabelece os critérios para aplicação de recursos nas despesas com ações e serviços públicos de saúde, especificando no art. 3º os itens que podem ser considerados para efeito de financiamento do SUS. Com a inclusão do inciso XIII pela LC nº 209/2024, passou a ser permitido aplicar recursos em","alternativas":["desenvolvimento científico e tecnológico, além do controle de qualidade promovidos por instituições do SUS.","atenção integral e universal à saúde em todos os níveis de atenção, incluindo assistência terapêutica e recuperação de deficiências nutricionais.","saneamento básico de domicílios ou de pequenas comunidades, desde que seja aprovado pelo Conselho de Saúde do ente da Federação financiador da ação.","custeio e investimento em hospitais universitários federais, inclusive por meio de entidade pública responsável por sua administração, desde que as despesas sejam aprovadas pelo Ministério da Saúde.","produção, aquisição e distribuição de insumos específicos dos serviços de saúde do SUS, tais como: imunobiológicos, sangue e hemoderivados, medicamentos e equipamentos médico- odontológicos"],"gabarito":"D"},{"n":37,"disciplina":"Legislação do SUS","assunto":"Redes de Atenção à Saúde","enunciado":"A regulação da assistência em saúde no SUS tem como objetivo principal promover a equidade do acesso. No que se refere à regulação da assistência em saúde no SUS, analise as afirmativas, classificando-as como verdadeira (V) ou falsa (F). ( ) A regulação ajusta a oferta disponível às necessidades imediatas do cidadão de forma ordenada e racional. ( ) O processo de regulação prescinde de avaliação prévia das necessidades de saúde e de planejamento/programação, já que sua atuação limita-se às situações emergenciais. ( ) A definição de estratégias de regionalização, com a responsabilização dos municípios na rede hierarquizada, integra as atribuições da regulação em saúde. As afirmativas são, respectivamente,","alternativas":["F – V – V.","V – F – V.","V – F – F.","F – V – F.","V – V – F."],"gabarito":"B"},{"n":38,"disciplina":"Legislação do SUS","assunto":"Lei 8.080/1990 - Organização e Competências","enunciado":"O art. 5º da Lei nº 8.080/1990 estabelece os objetivos do Sistema Único de Saúde (SUS), que orientam a formulação e execução das políticas públicas de saúde no Brasil. No que se refere aos objetivos do SUS, analise os itens a seguir, classificando-os como verdadeiro (V) ou falso (F). ( ) O SUS busca identificar e divulgar os fatores condicionantes e determinantes da saúde. ( ) É dever do Estado garantir a saúde a partir da formulação e execução de políticas previdenciárias que visem à redução de riscos de doenças e de outros agravos. ( ) Estão incluídas no campo de atuação do SUS a execução de ações de saúde do trabalhador e de saúde mental. As afirmativas são, respectivamente,","alternativas":["F – V – V.","V – F – V.","V – F – F.","F – V – F.","V – V – F"],"gabarito":"C"},{"n":39,"disciplina":"Legislação do SUS","assunto":"Lei 8.080/1990 - Princípios e Diretrizes","enunciado":"O Sistema Único de Saúde (SUS), nos termos do art. 7º da Lei nº 8.080/1990, deve observar, além das diretrizes constitucionais, princípios que orientam a prestação de serviços à população. Um desses princípios refere-se à organização das ações e serviços como um conjunto articulado e contínuo, envolvendo atividades preventivas e curativas, de caráter individual e coletivo, em todos os níveis de complexidade do sistema, de modo a assegurar que a atenção à saúde seja prestada de forma integrada e adequada às necessidades de cada caso. Esse princípio corresponde à","alternativas":["equidade.","universalidade de acesso.","participação da comunidade.","integralidade de assistência.","descentralização político-administrativa"],"gabarito":"D"},{"n":40,"disciplina":"Legislação do SUS","assunto":"Financiamento do SUS e LC 141/2012","enunciado":"O Fundo Nacional de Saúde (FNS) representa o principal instrumento de gestão financeira da União para viabilizar as políticas públicas de saúde. Com base na legislação vigente, assinale a afirmativa correta quanto às finalidades de alocação dos recursos do FNS.","alternativas":["Os recursos do FNS destinam-se majoritariamente a custear despesas de pessoal e encargos sociais do Ministério da Saúde, sendo vedado o uso deles em investimentos.","As alocações do FNS limitam-se às despesas de custeio do Ministério da Saúde e à execução de emendas parlamentares, não abrangendo planos de investimentos setoriais.","O financiamento do FNS está restrito às ações da administração direta do Ministério da Saúde, não contemplando entidades da administração indireta nem órgãos vinculados.","Os recursos do FNS têm aplicação exclusiva em investimentos previstos no Plano Nacional de Saúde, cabendo aos Estados e Municípios custear, com receitas próprias, a cobertura assistencial hospitalar.","A cobertura das ações e serviços de saúde, a serem implementados por Estados, Municípios e Distrito Federal, incluem investimentos na rede de serviços e na assistência ambulatorial e hospitalar."],"gabarito":"E"}]},{"id":"ni2025-acs","cargo":"Agente Comunitário de Saúde","prova":"https://conhecimento.fgv.br/sites/default/files/concursos/agente-comunitario-de-saude-acs-cnm001-tipo-1.pdf","gabarito":"https://conhecimento.fgv.br/sites/default/files/concursos/gabarito-definitivo-smsnovaiguacu.pdf","itens":[{"n":2,"disciplina":"Língua Portuguesa","assunto":"Semântica e Significação","enunciado":"Assinale a opção em que a palavra coisa(s) é substituída inadequadamente por um termo mais específico.","alternativas":["Você tem alguma coisa com aquela moça? (relação)","Discutiram sobre várias coisas no almoço. (assunto)","Alguma coisa aconteceu no trânsito hoje. (acidente)","Tem coisa estragada na geladeira. (alimento)","Não gosto que mexam nas minhas coisas. (dinheiro)"],"gabarito":"E"},{"n":3,"disciplina":"Língua Portuguesa","assunto":"Coesão e Coerência","enunciado":"Assinale a opção em que o verbo fazer tem função coesiva, retomando algo anteriormente enunciado.","alternativas":["Faz calor na cidade do Rio de Janeiro.","Assim que a professora entrou na sala, fizeram rapidamente o dever.","Não costuma frequentar teatro, mas o faz quando são peças de comédia.","Faz alguns anos que visitamos o Nordeste do país.","Fiz os procedimentos necessários para a cirurgia"],"gabarito":"C"},{"n":4,"disciplina":"Língua Portuguesa","assunto":"Interpretação de Textos","enunciado":"Na frase “tu te tornas eternamente responsável por aquilo que cativas”, só não se pode interpretar que","alternativas":["existe comprometimento duradouro com os laços criados.","há implicação efetiva nos afetos experimentados na vida.","há liberdade das relações entre as pessoas.","existe um envolvimento que não se finda.","existe um compromisso quanto às conexões estabelecidas"],"gabarito":"C"},{"n":6,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Proposições e Conectivos","enunciado":"O coordenador administrativo de uma empres a previu o quadro em que Maria seria transferida para a Bahia e o processo de licitação não seria concluído em tempo hábil. O quadro previsto pelo coordenador, no entanto, não se confirmou. Ou seja, o processo de licitação","alternativas":["foi concluído em tempo hábil, apesar de Maria ter sido transferida para a Bahia.","foi concluído em tempo hábil ou Maria não foi transferida para a Bahia.","não foi concluído por Maria fora da Bahia.","foi concluído em tempo hábil por Maria.","foi concluído em tempo hábil na Bahia"],"gabarito":"B"},{"n":7,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Sequências e Padrões","enunciado":"Uma sequência numérica possui a seguinte característica: a partir do segundo termo, cada termo é igual ao dobro do termo anterior. Portanto, se o sétimo termo dessa sequência é igual a 720, então o quarto termo é igual a","alternativas":["714.","360.","180.","90.","45"],"gabarito":"D"},{"n":8,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Argumentação Lógica","enunciado":"Quando finalizada, a planilha do orçamento mensal da Prefeitura passa por uma dupla revisão. Quando os dois revisores aprovam a planilha, ela é enviada para o prefeito; porém, quando os dois revisores a reprovam, ela é devolvida ao setor responsável. O caso restante faz com que a planilha seja enviada para um terceiro revisor. Ou seja, o caso restante é aquele em que","alternativas":["o setor responsável não pode fazer uma nova versão da planilha.","a planilha é grande demais para ser revisada por uma pessoa só.","um revisor aprova a planilha, mas o outro a reprova.","os revisores dão o mesmo parecer sobre a planilha.","a planilha não ficou pronta"],"gabarito":"C"},{"n":9,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Probabilidade","enunciado":"Em um Fórum, a probabilidade de um processo ser deferido é de 80%. Nesse Fóru m, a probabilidade de dois processos escolhidos ao acaso serem ambos indeferidos é de","alternativas":["50%.","40%.","25%.","20%.","4%."],"gabarito":"E"},{"n":10,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Razão, Proporção e Porcentagem","enunciado":"De 2023 para 2024, o aluguel de um imóvel foi reajustado em 14%. De 2024 para 2025, o aluguel do mesmo imóvel foi reajustado em 10%. De 2023 para 2025, portanto, o reajuste acumulado do aluguel do imóvel foi igual a","alternativas":["10,0%.","14,0%.","24,0%.","24,1%.","25,4%."],"gabarito":"E"},{"n":11,"disciplina":"Legislação do SUS","assunto":"Constituição Federal - Saúde","enunciado":"Analise os itens seguir sobre os dispositivos constitucionais que tratam da saúde, na Constituição Federal de 1988. I. A saúde é um direito de todos e dever do Estado. II. As ações de saúde são organizadas de forma regionalizada e hierarquizada. III. A in iciativa privada pode atuar no SUS, de forma complementar. Está correto o que se afirma em","alternativas":["I, apenas.","II e III, apenas.","I e II, apenas.","I, II e III.","III, apenas"],"gabarito":"D"},{"n":12,"disciplina":"Enfermagem","assunto":"Imunização","enunciado":"Uma equipe de saúde da família planeja uma campanha de vacinação infantil em sua área de abrangência. A Agente Comunitária de Saúde identifica crianças com cadernetas desatualizadas, a equipe organiza as ações de forma regionalizada em articulação com municípios vizinhos, e o Conselho Municipal de Saúde fiscaliza a execução da campanha. Esse exemplo ilustra a aplicação integrada de três marcos normativos do SUS. Assinale a opção que indica corretamente esses marcos e suas respectivas contribuições.","alternativas":["A Lei nº 8.080/1990 define a saúde como direito de todos e dever do Estado, a Lei nº 8.142/1990 reforça a participação popular por meio de conselhos e conferências, e o Decreto nº 7.508/2011 detalha a organização territorial e os pactos interfederativos do SUS.","A Lei nº 8.080/1990 define as competências das três esferas de governo, a Lei nº 8.142/1990 estabelece os critérios de repasse de recursos federais, e o Decreto nº 7.508/2011 regulamenta a atuação da iniciativa privada no SUS.","A Lei nº 8.080/1990 trata da organização dos serviços de saúde, a Lei nº 8 .142/1990 disciplina o controle de qualidade de imunobiológicos, e o Decreto nº 7.508/2011 estabelece as diretrizes para campanhas nacionais de vacinação.","A Lei nº 8.080/1990 estabelece os princípios e diretrizes do SUS, a Lei nº 8.142/1990 regulamenta a gestão financeira dos hospitais públicos, e o Decreto nº 7.508/2011 define as atribuições exclusivas dos agentes comunitários de saúde.","A Lei nº 8.080/1990 define as competências do Ministério da Saúde, a Lei nº 8.142/1990 estabelece as normas para contratação de profissionais de saúde, e o Decreto nº 7.508/2011 regulamenta a dispensação de medicamentos nas farmácias populares."],"gabarito":"A"},{"n":13,"disciplina":"Legislação do SUS","assunto":"Atenção Primária e PNAB","enunciado":"Durante visitas domiciliares no território, a Agente Comunitária de Saúde (ACS) percebe que algumas famílias têm dificu ldade de manter o acompanhamento pré -natal, e outras em realizar atividades físicas de forma regular. Ela também recebeu algumas críticas sobre o atendimento na Unidade Básica de Saúde. Para colaborar com a resolução desses desafios, a equipe planeja três grupos de ações: 1. visitas domiciliares frequentes às gestantes e às pessoas com hipertensão, com registros sistematizados em conjunto com a equipe de saúde; 2. articulação com escolas, associações e feiras locais para promover oficinas de alimentação saudável, incentivar grupos de caminhada e facilitar o acesso a alimentos in natura; 3. participação na implantação na Unidade Básica de Saúde de protocolos de acolhimento com escuta qualificada e incentivo à participação da comunidade na avaliação do serviço. Considerando o foco principal de cada ação, assinale a opção que indica as políticas públicas do SUS relacionadas a 1, 2 e 3, respectivamente.","alternativas":["Política Nacional de Atenção Básica — Política Nacional de Promoção da Saúde — Política Nacional de Humanização","Política Nacional de Humanização — Política Nacional de Atenção Básica — Política Nacional de Promoção da Saúde","Política Nacional de Atenção Básica — Política Nacional de Humanização — Política Nacional de Promoção da Saúde","Política Nacional de Promoção da Saúde — Política Nacional de Atenção Básica — Política Nacional de Humanização","Política Nacional de Atenção Básica — Política Nacional de Promoção da Saúde — Controle Social no SUS"],"gabarito":"A"},{"n":14,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"Leia a frase a seguir. A vigilância __________ atua no controle de surtos, epidemias e doenças transmissíveis, sendo fundamental para a identificação precoce de riscos à saúde coletiva. Assinale a opção cujo item completa corretamente a lacuna do fragmento lido.","alternativas":["sanitária","ambiental","epidemiológica","ocupacional","alimentar"],"gabarito":"C"},{"n":15,"disciplina":"Legislação do SUS","assunto":"Lei 8.080/1990 - Princípios e Diretrizes","enunciado":"Sobre os princípios e as diretrizes do Sistema Único de Saúde (SUS), analise as afirmativas a seguir, classificando -as como verdadeira (V) ou falsa (F). ( ) O SUS representa um marco histórico na ga rantia do direito à saúde no Brasil. Antes do SUS, o acesso aos serviços era restrito principalmente aos trabalhadores formais, vinculados à previdência. ( ) O princípio da participação social assegura o acesso de toda a população ao SUS, sem discrimina ção, já o princípio da igualdade garante que pessoas em situações desiguais recebam atenção diferenciada, de acordo com suas necessidades. ( ) A integralidade é um princípio doutrinário do SUS, ao assegurar que a atenção à saúde contemple ações de promoção, prevenção, tratamento e reabilitação, considerando a pessoa em sua totalidade. As afirmativas são, respectivamente,","alternativas":["V – V – V.","V – F – V.","F – V – F.","V – F – F.","V – V – F. Saúde, Comunidade e Território"],"gabarito":"B"},{"n":16,"disciplina":"Legislação do SUS","assunto":"Atenção Primária e PNAB","enunciado":"Durante uma visita domiciliar, a Agente Comunitária de Saúde (ACS) percebe que uma gestante apresenta sinais de desnutrição e baixa frequência de consultas pré -natais. A ACS deve agir de maneira a priorizar a atenção a essa gestante, considerando as atribuições do seu papel. Prioritariamente, a ação mais adequada seria","alternativas":["orientar a gestante a procurar imediatamente um hospital para avaliação e tratamento.","registrar o caso e aguardar que a equipe de saúde agende uma consulta especializada na Unidade de Pronto Atendimento.","orientar a gestante sobre a importância do pré -natal e encaminhá-la à Unidade de Saúde para garantir o atendimento adequado e regular.","sugerir que a gestante procure um nutricionista particular para avaliação imediata.","acionar uma Unidade de Pronto Atendimento, pois não é função da ACS intervenções clínicas ou diagnósticas"],"gabarito":"C"},{"n":17,"disciplina":"Legislação do SUS","assunto":"Atenção Primária e PNAB","enunciado":"Durante visita domiciliar, uma ACS identificou uma família com criança de quatro anos em atraso vacinal, gestante sem pré -natal e idoso com hipertensão não controlada. A ACS orientou a família a procurar a Unidade Básica de Saúde (UBS), registrou as informações no sistema e comunicou à equipe da Estratégia Saúde da Família (ESF). Considerando a Lei nº 11.350/2006 e as atribuições do ACS, assinale a afirmativa correta.","alternativas":["A ACS deveria ter agendado as consultas diretamente com os especialistas na UBS antes de comunicar à equipe da ESF, conforme previsto em lei.","A ACS agiu corretamente ao realizar orientação, registro das informações, visi ta domiciliar periódica e encaminhamento para a equipe multiprofissional, atribuições previstas em lei.","A atuação da ACS foi inadequada, pois a identificação de atraso vacinal, pré -natal e hipertensão são responsabilidades exclusivas de médicos e enfermeiros.","A ACS deveria ter priorizado apenas o acompanhamento da gestante e do idoso, pois o atraso vacinal infantil requer intervenção exclusiva do enfermeiro.","A ACS só deve atuar em campanhas de vacinação e em ações previamente programadas pela Secretaria Municipal de Saúde, não em situações identificadas durante visitas domiciliares"],"gabarito":"B"},{"n":18,"disciplina":"Legislação do SUS","assunto":"Atenção Primária e PNAB","enunciado":"Um dos papéis fundamentais do Agente Comunitário de Saúde (ACS) é fomentar a promoção da saúde e a prevenção de doenças no contexto comunitário. Imagine que, em uma determinada comunidade, há uma alta incidência de diabetes não controlada. Uma ação que pode ajudar na prevenção e no controle da doença é","alternativas":["priorizar o ensino para as crianças sobre a importância da saúde.","sugerir uma feira comunitária para venda de produtos artesanais, como compotas, geleias e pães.","encaminhar os usuários para cons ultas médicas frequentes, deixando as explicações adicionais para a enfermeira da equipe multiprofissional.","realizar visitas domiciliares, para conversar sobre hábitos saudáveis.","organizar festas mensais para confraternização, sugerindo que os próp rios usuários produzam bolos e doces, de forma a fortalecer o vínculo"],"gabarito":"D"},{"n":19,"disciplina":"Legislação do SUS","assunto":"Atenção Primária e PNAB","enunciado":"Sobre as atribuições do Agente Comunitário de Saúde, analise as afirmações a seguir e assinale (V) para verdadeira ou (F) para falsa. ( ) Fazer a busca ativa dos faltosos às va cinas e consultas aos programas prioritários. ( ) Orientar a aplicação da vacina BCG no 9º mês de vida. ( ) Prevenir acidentes na infância, evitando sequelas graves. ( ) Incentivar o aleitamento materno, que é uma das estratégias mais eficazes para redução de adoecimento e morte infantil. As afirmativas são, respectivamente,","alternativas":["V – V – V – V.","V – F – V – V.","F – V – F – V.","V – F – F – V.","V – V – F – F"],"gabarito":"B"},{"n":20,"disciplina":"Legislação do SUS","assunto":"Atenção Primária e PNAB","enunciado":"Com base no conceito de território, área e microárea, é correto afirmar que","alternativas":["o território é definido pela gestão municipal, sendo uma divisão administrativa fixa.","a microárea é o espaço de atuação de cada ACS, permitindo identificar problemas específicos das famílias e comunidades.","a área corresponde ao município como um todo, e não se relaciona com a divisão em equipes de saúde.","a microárea corresponde a um domicílio acompanhado pelo ACS, facilitando o vínculo e o cuidado longitudinal das famílias.","o ACS deve atuar somente na Unida de de Saúde, não é sua função identificar problemas ambientais no território."],"gabarito":"B"},{"n":21,"disciplina":"Legislação do SUS","assunto":"Atenção Primária e PNAB","enunciado":"Sobre o uso do mapeamento territorial e do diagnóstico comunitário pelo ACS, é correto afirmar que","alternativas":["o mapeamento territorial identifica a localização dos domicílios, sen do o diagnóstico das condições de saúde realizado posteriormente pela equipe multidisciplinar (eMulti).","o diagnóstico comunitário é subsídio para gerar dados epidemiológicos oficiais, sendo as informações coletadas pelo ACS complementares e secundárias.","o uso do mapeamento e das visitas domiciliares permite identificar fatores sociais e ambientais que influenciam a saúde da comunidade.","o mapeamento territorial tem finalidade cadastral, enquanto a identificação de fatores de risco ambientais comp ete à Vigilância Sanitária.","o diagnóstico das condições de saúde baseia -se em indicadores quantitativos, não incluindo aspectos sociais e culturais observados nas visitas"],"gabarito":"C"},{"n":22,"disciplina":"Legislação do SUS","assunto":"Atenção Primária e PNAB","enunciado":"Sobre as ferramentas de trabalho do Agente Comunitário de Saúde, analise as afirmativas a seguir, classificando -as como verdadeira (V) ou falsa (F). ( ) Realizar o cadastro e identificar os principais problemas de saúde contribui para que os serviços possam oferecer uma atenção mais voltada para a família, de acordo com a realidade e os problemas de cada comunidade. ( ) Os profissionais devem atuar de forma integrada, discutindo, analisando em equipe e atualizando as situações identificadas no território, pois tão importante quanto fazer o cadastro da população é mantê-lo atualizado. ( ) Conhecer o número de pessoas da comunidade por faixa etária e sexo é importante, pois há doenças que acometem mais crianças do que adultos ou mais mulheres que homens, o que influenciará no planejamento em saúde. ( ) Ao realizar os cadastro s individuais e domiciliares, o preenchimento das informações deve ser o mais completo possível, pois elas são importantes ferramentas para compreendermos quem são as pessoas que vivem no território, favorecendo o planejamento de ações para essa população. As afirmativas são, respectivamente,","alternativas":["V – V – V – V.","V – F – V – V.","F – V – F – V.","V – F – F – V.","V – V – F – F"],"gabarito":"A"},{"n":23,"disciplina":"Legislação do SUS","assunto":"Atenção Primária e PNAB","enunciado":"Em relação ao desfecho de uma visita domiciliar, analise as possibilidades de registro a seguir. I. “Visita realizada”, se ocorreu de acordo com o planejado pelo profissional. II. “Visita recusada”, se o cidadão recusa a visita, impossibilitando realizar a ação pretendida. III. “Ausente”, se o cidadão procurado estava ausente ou não foi possível contatá-lo. Está correto o que se afirma em","alternativas":["I, II e III.","II e III, apenas.","I e II, apenas.","III, apenas.","I e III, apenas"],"gabarito":"A"},{"n":25,"disciplina":"Legislação do SUS","assunto":"Atenção Primária e PNAB","enunciado":"Sobre as atribuições do Agente Com unitário de Saúde, analise as afirmativas a seguir, classificando-as como verdadeira (V) ou falsa (F). ( ) O ACS deve realizar visitas domiciliares periódicas, registrar as informações no sistema e comunicar à equipe multiprofissional. ( ) A promoção de ações educativas, sobre a importância da vacinação, do pré -natal e do controle da hipertensão, está entre as atribuições do ACS. ( ) Cabe ao ACS prescrever medicamentos e solicitar exames laboratoriais, quando o profissional identifica necessidade de acompanhamento de usuários com doenças crônicas não transmissíveis, como a hipertensão. ( ) A atuação do ACS contribui para a integralidade da atenção, ao articular prevenção, promoção e acompanhamento no território. As afirmativas são, respectivamente,","alternativas":["V – V – F – V.","V – F – V – V.","F – V – V – F.","V – V – V – F.","F – F – V – V."],"gabarito":"A"},{"n":26,"disciplina":"Legislação do SUS","assunto":"Atenção Primária e PNAB","enunciado":"Em uma comunidade, a equipe de saúde percebeu altos índices de obesidade infantil. A Agente Comunitária de Saúde (ACS) foi chamada para colaborar na execução de um projeto educativo intersetorial. A proposta incluía rodas de conversa nas escolas sobre alimentação saudável e incentivo à prática de esportes, em parceria com a associação de moradores. Em relação aos princípios de promoção da saúde e educa ção em saúde, é correto afirmar que","alternativas":["a ACS pode desenvolver ações educativas apenas sob supervisão da equipe, priorizando o domicílio.","a ação descrita exemplifica promoção da saúde, pois envolve estratégias intersetoriais e participação.","a obesidade infantil deve ser acompanhada pela equipe multiprofissional, cabendo ao ACS planejar e orientar sobre o tratamento.","as ações educativas devem seguir roteiros padronizados, sem considerar especificidades da comunidade local.","a promoção da saúde inclui prevenção de doenças em nível individual e deve priorizar o tratamento e intervenções clínicas"],"gabarito":"B"},{"n":27,"disciplina":"Enfermagem","assunto":"Arboviroses (Dengue, Zika, Chikungunya, Febre Amarela, Oropouche e Nilo Ocidental)","enunciado":"Uma Agente Comunitária de Saúde (ACS) identificou que várias famílias da microárea apresentavam armazenamento inadequado de água, favorecendo a proliferação de mosquitos transmissores de arboviroses (Dengue, Zika, Chikungunya). A equipe da Estratégia Saúde da Família decidiu planejar uma ação educativa comunitária para enfrentar o problema. Com base nos conceitos de educação em saúde e promoção da saúde, é correto afirmar que","alternativas":["a atuação do ACS deve concentrar -se no acompanhamento domiciliar, deixando as ações intersetoriais sob responsabilidade dos demais profissionais da equipe.","a intersetorialidade é importante, mas a efetividade das ações depende principalmente da adesão individual das famílias às orientações sobre a água potável.","as ações educativas devem seguir um modelo único definido pela Secretaria Municipal de Saúde, garantindo padronização e uniformidade das práticas em todos os territórios.","o planejamento deve considerar as características socioculturais da comunidade, incentivando a participação ativa das famílias na busca de soluções.","o papel do ACS limita-se a apoiar logisticamente as atividades coletivas, sem necessidade de envolvimento direto nas rodas de conversa ou nas parcerias com instituições locais"],"gabarito":"D"},{"n":28,"disciplina":"Enfermagem","assunto":"Imunização","enunciado":"A vacina contra o HPV é oferecida gratuitamente pelo SUS e protege contra o câncer. Uma ACS percebeu que muitos adolescentes e responsáve is apresentavam dúvidas sobre a segurança da vacina e sua necessidade para meninos. Algumas famílias recusavam a vacinação por acreditarem que poderia estimular o início precoce da vida sexual. Nesse contexto, com base nas atribuições do ACS, é correto afirmar que","alternativas":["a ACS deve encaminhar a família à UBS para esclarecimentos com o enfermeiro, pois dúvidas sobre vacinas exigem conhecimento técnico específico que não faz parte de suas atribuições.","a ACS deve respeitar a decisão da família e orientar sob re os riscos da não vacinação, mas não deve insistir caso a recusa seja mantida, priorizando a autonomia familiar.","a ACS deve orientar corretamente que a vacina contra o HPV é segura, protege contra o câncer e deve ser aplicada em meninas e meninos, reforçando que a imunização não estimula o início da vida sexual.","a vacinação contra o HPV deve ser ofertada apenas a adolescentes já em vida sexual ativa, não sendo indicada de forma preventiva.","a ACS deve focar na orientação sobre o uso de preservativos como principal forma de prevenção, pois a vacina tem eficácia limitada e não substitui outras medidas preventivas"],"gabarito":"C"},{"n":29,"disciplina":"Enfermagem","assunto":"Saúde da Mulher","enunciado":"O câncer do colo do útero é o terceiro mais incidente em mulheres brasileiras e tem como principal causa o HPV. Durante visitas domiciliares, uma ACS identificou que muitas mulheres não realizavam o exame citopatológico regularmente, alegando falta de tempo, vergonha e desconhecimento. A ACS propôs organizar grupo educativo e reforçar convites individuais durante as visitas. Com base nas atribuições do ACS, é correto afirmar que","alternativas":["a ACS deve registrar a situação e encaminhar o problema para a equipe de enfermagem, pois ações educativas sobre exames ginecológicos exigem conhecimento técnico específico.","a ACS atuou corretamente ao identificar barreiras culturais e práticas, propor ações educativas coletivas e reforçar a importância do exame durante as visitas domiciliares.","a ACS deve priorizar a orientação individual durante as visitas, pois grupos educativos sobre exames ginecológicos podem gerar constrangimento entre as participantes.","a captação de mulheres para o exame citopatológico é atribuição do médico e do enfermeiro, cabendo ao ACS apenas o registro de faltosas no sistema.","a ACS deve focar na prevenção primária por meio da vacinação contra HPV, pois o rastreamento com exame citopatológico compete à atenção especializada."],"gabarito":"B"},{"n":30,"disciplina":"Enfermagem","assunto":"Hipertensão Arterial","enunciado":"A hiperte nsão arterial é uma doença crônica muitas vezes assintomática, mas que pode gerar complicações graves como AVC e infarto. Durante visita domiciliar, uma ACS percebeu que um morador com hipertensão havia abandonado o tratamento porque \"se sentia bem\" e não apresentava sintomas. Nesse caso, a orientação correta da ACS seria","alternativas":["explicar que a hipertensão muitas vezes não causa sintomas, mas pode gerar complicações graves, sendo fundamental manter o tratamento e o acompanhamento.","orientar que o usuário retorne à UBS para reavaliação médica antes de decidir pela continuidade do tratamento, respeitando sua percepção sobre o próprio corpo.","reforçar a importância do tratamento, mas informar que medicamentos podem ser suspensos temporariamente quando a pressão está controlada e não há sintomas.","explicar que o controle da hipertensão também pode ser feito com mudanças no estilo de vida, podendo o usuário reduzir gradualmente a medicação se mantiver dieta adequada e atividade física.","registrar a informação e encaminhar o caso para o enfermeiro ou médico, pois orientações sobre adesão ao tratamento medicamentoso exigem conhecimento técnico específico"],"gabarito":"A"},{"n":31,"disciplina":"Enfermagem","assunto":"Diabetes Mellitus","enunciado":"Uma Agente Comunitária de Saúde (ACS) encontrou um usuário com Diabetes Mellitus que apresentava fer idas nos pés, usava calçados apertados e relatava que não fazia acompanhamento regular na Unidade Básica de Saúde. Ele acreditava que apenas controlar a alimentação seria suficiente para evitar complicações. Nessa situação, a conduta correta da ACS é","alternativas":["reforçar a importância do controle alimentar e orientar que o acompanhamento na Unidade só é necessário se as feridas piorarem.","explicar que as complicações do Diabetes podem incluir úlceras e amputações, orientar sobre o cuidado diário com os pés, uso de calçados adequados e reforçar a importância do acompanhamento regular na Unidade de Saúde.","reforçar que a própria ACS, durante as visitas domiciliares, pode tratar as feridas nos pés com pomadas caseiras, evitando a necessidade de encaminhamento para a Unidade de Saúde.","encaminhar o usuário diretamente à Unidade de Pronto Atendimento, para um acompanhamento mais eficaz nesse caso.","informar que o acompanhamento do Diabetes deve ser feito apenas em hospitais, não cabendo à Atenção Básica"],"gabarito":"B"},{"n":32,"disciplina":"Enfermagem","assunto":"Saúde Mental","enunciado":"Durante visita domiciliar, uma ACS encontrou usuário em sofrimento psíquico grave, com crises frequentes e isolamento. A família não sabia a quem recorrer, acreditando que apenas hospitais psiquiátricos poderiam atender. A ACS orientou, registrou e co municou à equipe da Estratégia Saúde da Família (ESF). Considerando as atribuições da ACS e a Rede de Atenção Psicossocial (RAPS), a conduta adequada seria","alternativas":["orientar a família a procurar atendimento de urgência no hospital geral mais próximo, pois casos de sofrimento psíquico grave exigem internação imediata.","encaminhar a situação para avaliação da equipe da ESF, que poderá prescrever medicação inicial e agendar consulta com psiquiatra no serviço especializado.","explicar que o usuário pode ser aco mpanhado pelo CAPS (Centro de Atenção Psicossocial), serviço especializado em saúde mental, articulado com a ESF, para garantir cuidado territorial e comunitário.","informar que o cuidado em saúde mental requer acompanhamento exclusivo por psicólogo ou p siquiatra, não sendo atribuição da Atenção Básica esse tipo de acompanhamento.","orientar a família sobre técnicas de manejo de crise e iniciar acompanhamento terapêutico domiciliar, até que o usuário apresente melhora dos sintomas"],"gabarito":"C"},{"n":33,"disciplina":"Enfermagem","assunto":"Saúde da Criança e do Adolescente","enunciado":"Uma criança não estava se desenvolvendo conforme os marcos apresentados na caderneta da criança. A mãe decidiu buscar atendimento para um possível diagnóstico. Seu filho, uma criança de 4 anos, apresentava atraso na fala, dificuldade de interação social e comportamentos repetitivos. Nessa situação, o Agente Comunitário de Saúde (ACS) deve","alternativas":["encaminhar a criança para consulta com o psiquiatra, pois, dependendo do diagnóstico, necessitará de prescrição de medicamentos.","orientar a família a observar o compo rtamento da criança e procurar a escola para verificar se as dificuldades se repetem em outros ambientes.","priorizar as ações de imunização e vigilância epidemiológica e encaminhar para tratamento em hospital especializado.","orientar a família a observar o comportamento por mais alguns meses antes de procurar novamente a unidade, pois atrasos no desenvolvimento são comuns nessa faixa etária.","orientar sobre a importância do acompanhamento precoce, encaminhar para avaliação pela equipe multiprofis sional em articulação com o Centro de Atenção Psicossocial Infantil (CAPSi)."],"gabarito":"E"},{"n":34,"disciplina":"Enfermagem","assunto":"Imunização","enunciado":"Em 21 de dezembro de 2023, a vacina contra a Dengue foi incorporada no Sistema Único de Saúde (SUS), tornando o Brasil o primeiro país do mundo a oferecer o imunizante no sistema público de saúde. Com relação à vacina Qdenga, produzida pelo laboratório japonês Takeda, assinale a afirmativa correta.","alternativas":["É uma vacina tetravalente produzida a partir de vírus atenuados, possui esquema vacinal composto por duas doses com intervalo de 60 dias entre elas, e é indicada para gestantes.","É uma vacina tetravalente produzida a partir de vírus atenuados, possui esquema vacinal composto por duas doses com intervalo de 90 dias entre elas e é contraindicada para gestantes.","É uma vacina tetravalente produzida a partir de vírus inativados, possui esquema vacinal compo sto por duas doses com intervalo de 60 dias entre elas, e é indicada para gestantes.","É uma vacina tetravalente produzida a partir de vírus inativados, possui esquema vacinal composto por duas doses com intervalo de 90 dias entre elas, e é contraindicad a para gestantes.","É uma vacina tetravalente produzida a partir de vírus inativados, possui esquema vacinal composto por duas doses com intervalo de 90 dias entre elas, e é indicada para gestantes"],"gabarito":"B"},{"n":36,"disciplina":"Enfermagem","assunto":"Imunização","enunciado":"Existem mais de 200 tipos de HPV (papilomavírus humano), os quais podem causar desde verrugas genitais a câncer do colo do útero, ânus, pênis, boca e garganta. É importante destacar que o câncer do colo do útero é o terceiro tipo de tumor mais frequente na população feminina e que a vacinação é a melhor forma de prevenção. Com relação à vacina contra o HPV oferecida gratuitamente pelo SUS, assinale a opção correta.","alternativas":["É uma vacina tetravalente (protege contra os tipos 6, 11, 16 e 18), possui esquema vacin al composto por dose única, e tem como público -alvo principal meninas e meninos de 9 a 14 anos.","É uma vacina tetravalente (protege contra os tipos 6, 11, 16 e 18), possui esquema vacinal composto por três doses com dois meses de intervalo entre cada uma, e tem como público -alvo principal meninas e meninos de 9 a 14 anos.","É uma vacina tetravalente (protege contra os tipos 6, 11, 16 e 18), possui esquema vacinal composto por três doses com dois meses de intervalo entre cada uma, e tem como público -alvo principal meninas e meninos de 9 a 19 anos.","É uma vacina nonavalente (protege contra os tipos 6, 11, 16, 18, 31, 33, 45, 52 e 58), possui esquema vacinal composto por dose única, e tem como público -alvo principal meninas e meninos de 9 a 14 anos.","É uma vacina nonavalente (protege contra os tipos 6, 11, 16, 18, 31, 33, 45, 52 e 58), possui esquema vacinal composto por três doses com dois meses de intervalo entre cada uma, e tem como público -alvo principal meninas e meninos de 9 a 19 anos"],"gabarito":"A"},{"n":37,"disciplina":"Enfermagem","assunto":"Arboviroses (Dengue, Zika, Chikungunya, Febre Amarela, Oropouche e Nilo Ocidental)","enunciado":"No que se refere aos sorotipos do vírus da Dengue, analise as afirmativas a seguir. I. Todos os quatro sorotipos do vírus da Dengue (DENV-1, DENV- 2, DENV -3 e DENV -4) circulam no Brasil atualmente, mas de maneira alternada nas diferentes regiões. II. A infecção por um sorotipo do vírus da Dengue confere imunidade permanente e específica contra aquele sorotipo, mas não contra os outros três. III. Em 2024, os casos de dengue associados ao sorotipo DENV -3 aumentaram significativamente no Bra sil. Esse sorotipo é considerado um dos mais virulentos e com maior potencial de causar Dengue grave. Além disso, não circulava de forma predominante no país desde 2008, o que torna grande parte da população suscetível a ele. Está correto o que se afirma em","alternativas":["I, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III."],"gabarito":"E"},{"n":38,"disciplina":"Enfermagem","assunto":"Arboviroses (Dengue, Zika, Chikungunya, Febre Amarela, Oropouche e Nilo Ocidental)","enunciado":"A dengue é uma doença febril aguda, sistêmica e dinâmica, que pode se manifestar desde formas assintomáticas e leves até formas graves e fatais. O reconh ecimento precoce dos sinais de alarme da Dengue é crucial para evitar o agravamento da doença. Assinale a opção que indica somente exemplos de sinais de alarme da Dengue.","alternativas":["Dor abdominal intensa e contínua, letargia e/ou irritabilidade e dor nas articulações.","Dor atrás dos olhos, vômitos persistentes e sangramento de mucosas.","Letargia e/ou irritabilidade, dificuldade de respirar e febre alta.","Dor abdominal intensa e contínua, vômitos persistentes e sangramento de mucosas.","Manchas v ermelhas no corpo, febre alta e dificuldade de respirar"],"gabarito":"D"},{"n":39,"disciplina":"Enfermagem","assunto":"Arboviroses (Dengue, Zika, Chikungunya, Febre Amarela, Oropouche e Nilo Ocidental)","enunciado":"No que se refere ao vírus Zika (ZIKV), assinale (V) para a afirmativa verdadeira e (F) para a falsa. ( ) A maioria das infecções pelo ZIKV é assintomática (cerca de 80%), porém a ausência de sintomas não impede a transmissão do vírus nem o desenvolvimento de complicações neurológicas. ( ) A principal forma de transmissão do ZIKV é vetorial (pela picada do mosquito Aedes Aegypti ), porém, a transmissão vertical e a transmissão sexual também podem ocorrer. ( ) A transmissão vertical do ZIKV pode ocorrer ao longo de todo o período gestacional, tanto na ausência como na presença de sintomas na mãe, entretanto, o risco de desenvolver a Síndrome Congênita do vírus Zika (SCZ) é maior entre as mulheres infectadas durante o terceiro trimestre. As afirmativas são, respectivamente,","alternativas":["F – F – F.","V – V – F.","F – V – F.","F – F – V.","V – F – F"],"gabarito":"B"},{"n":40,"disciplina":"Enfermagem","assunto":"Tuberculose","enunciado":"A tuberculose (TB) é uma doença infecciosa causada pela bactéria Mycobacterium tuberculosis , também conhecida como bacilo de Koch. Apesar de ser uma enfermidade antiga, continua sendo um importante problema de saúde pública. Com relação ao tratamento da TB, examine as afirmativas a seguir. I. O tratamento da TB pulmonar é realizado com múltiplos fármacos e tem a duração mínima de 6 meses. II. O tratamento da TB resistente é mais complexo e prolongado, podendo durar até 9 meses. III. O Tratamento Diretame nte Observado (TDO), com a administração dos medicamentos sendo realizada sob observação direta de um profissional de saúde, é fundamental para garantir a adesão dos pacientes. Está correto o que se afirma em","alternativas":["I, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III."],"gabarito":"C"}]}] as const;
export async function sincronizarFGVNovaIguacu2025() {
 const u=await prisma.usuario.findFirst({orderBy:{id:"asc"},select:{id:true}});
 if(!u) return {inseridas:0,existentes:0,repetidas:0};
 const norm=(s:string)=>s.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g," ").trim();
 const anteriores=await prisma.questao.findMany({where:{fonte:FONTE_PROVAS_REAIS},select:{enunciado:true}});
 const conhecidos=new Set(anteriores.map(q=>norm(q.enunciado)));
 const disciplinas=new Map<string,number>();let inseridas=0,existentes=0,repetidas=0;
 for(const lote of LOTES)for(const q of lote.itens) {
  const origemId="fgv-"+lote.id+"-tipo1-q"+String(q.n).padStart(2,"0");
  if(!q.enunciado.trim()||q.alternativas.length!==5||q.alternativas.some(a=>!a.trim())||
     !["A","B","C","D","E"].includes(q.gabarito)||new Set(q.alternativas.map(a=>a.toLowerCase().trim())).size!==5)
     throw new Error("[novaiguacu-2025] Alternativas inválidas "+origemId);
  if(await prisma.questao.findFirst({where:{fonte:FONTE_PROVAS_REAIS,origemId},select:{id:true}})){existentes++;continue;}
  const hash=norm(q.enunciado);if(conhecidos.has(hash)){repetidas++;continue;}
  let disciplinaId=disciplinas.get(q.disciplina);
  if(!disciplinaId){
   let d=await prisma.disciplina.findFirst({where:{usuarioId:u.id,nome:{equals:q.disciplina,mode:"insensitive"}},select:{id:true}});
   if(!d)d=await prisma.disciplina.create({data:{usuarioId:u.id,nome:q.disciplina},select:{id:true}});
   disciplinaId=d.id;disciplinas.set(q.disciplina,disciplinaId);
  }
  await prisma.questao.create({data:{
   usuarioId:u.id,disciplinaId,tema:q.assunto,fonte:FONTE_PROVAS_REAIS,origemId,
   dificuldade:"medio",banca:"FGV",ano:2025,orgao:"Secretaria Municipal de Saúde de Nova Iguaçu",
   cargo:lote.cargo,fonteUrl:lote.prova,enunciado:q.enunciado,
   explicacao:"FGV/Nova Iguaçu 2025, "+lote.cargo+", Tipo 1, questão "+q.n+
      ". Gabarito definitivo: alternativa "+q.gabarito+". Caderno: "+lote.prova+" | Gabarito: "+lote.gabarito,
   alternativas:{create:q.alternativas.map((texto,i)=>({texto:"ABCDE"[i]+") "+texto,correta:"ABCDE"[i]===q.gabarito}))}
  }});
  conhecidos.add(hash);inseridas++;
 }
 console.log("[novaiguacu-2025] "+inseridas+" inseridas; "+existentes+" existentes; "+repetidas+" duplicadas ignoradas.");
 return {inseridas,existentes,repetidas};
}
